Object.assign(window.__SYN,{"c:弦+沉+紧": {"o": "沉弦紧脉总属阴寒内盛、阳气被遏之候。沉主里，弦主饮主痛主气郁，紧主寒主痛主结，三象合见，多因寒邪深踞于里，或寒积内结，或寒饮痰凝，或寒凝肝脉，致气机凝滞、脉道拘急。其病机以寒为核心，或兼积、兼饮、兼气滞，甚则阳虚无力鼓动。各段原文多从‘沉主里，弦主饮主痛，紧主寒’立论，治法以温通为主，如温脾法、通脉四逆汤、桂附温经等，反证其病机属寒属里。诸类之间，寒邪为共同基础，积、饮、气滞、阳虚为不同兼夹，临床当结合兼症辨其孰轻孰重。", "c": [{"name": "主里寒", "desc": "沉主里，紧主寒，弦亦主寒。原文多言‘沉主里，紧主寒’，如太阴湿疟、厥阴伤寒、寒饮内停等，皆因寒邪在里，阳气被遏，脉道拘急，故见沉弦紧。"}, {"name": "主寒积内结", "desc": "弦紧主痛主结，沉主里。原文如‘素有肝胃气痛，兼挟寒积’、‘腹中必有宿食’、‘恐属脏结’，皆寒积深结于里，气机凝滞，故脉沉弦紧，按之凝滞。"}, {"name": "主寒饮痰凝", "desc": "弦主饮，紧主寒，沉主里。原文如‘沉弦主饮，紧则为寒’、‘重按滑而硬’为寒痰胶结，或呕逆不渴、肢冷麻木，皆寒饮痰湿内停，阻遏阳气，脉道拘急而见沉弦紧。"}, {"name": "主寒凝肝脉", "desc": "弦主肝、主痛，紧主寒，沉主里。原文如‘肝经积冷，结为冲疝’、‘厥阴伤寒，厥气上逆’，寒邪凝滞肝脉，气机逆乱，故脉沉弦紧，并见胁痛、少腹冷痛、手足厥冷。"}, {"name": "主阳虚寒盛", "desc": "沉弦紧而无力，或沉缓无神，为阳虚寒盛之象。原文如‘脉沉弦紧而无力’断为厥阴伤寒阳虚，阴寒白喉脉沉紧而弦或沉缓无神，皆阳气不振，阴寒内盛，脉道失于温通。"}], "n": {"主里寒": 2, "主寒积内结": 6, "主寒饮痰凝": 3, "主寒凝肝脉": 3, "主阳虚寒盛": 2}, "a": {"5586": "主里寒", "5686": "主寒凝肝脉", "8439": "主寒积内结", "10852": "主寒积内结", "10856": "主寒积内结", "13668": "主寒积内结", "14779": "主寒积内结", "14805": "主寒积内结", "16107": "主寒凝肝脉", "16112": "主阳虚寒盛", "16141": "主寒饮痰凝", "16154": "主里寒", "16206": "主寒凝肝脉", "16223": "主寒饮痰凝", "16224": "主寒饮痰凝", "16727": "主阳虚寒盛"}, "t": 16, "np": 0}, "c:细+沉+紧": {"o": "沉细紧脉总属里、虚、寒三象交织，以寒邪内盛、阳气虚衰为核心。沉主病在里，细主阴血不足或阳气虚，紧主寒主痛，三者相合，多示里寒证。其具体所主，或为单纯里寒，或为虚寒内生，或寒凝成积，或寒凝血瘀，或寒伤血络而气不摄血，甚则寒盛阳衰、少阴证全。各证虽表现不同，但病机一脉相承：寒邪为患，阳气受损，气血凝滞。脉沉细紧既可见于新寒直中，亦可见于久病阳衰，总以温通扶阳为治，忌苦寒清滋。", "c": [{"name": "主里寒", "desc": "沉主里，紧主寒，细为阳虚，合为里寒之象。原文多称‘沉寒痼冷’‘中寒’‘阴寒内盛’，如胸脘痛遇寒加重、少阴证全、肾脉本脉等，皆因寒邪在里，阳气不运，故脉沉细紧。"}, {"name": "主寒凝积滞", "desc": "紧主寒主痛，细主积，沉主里，寒凝气滞日久成积。原文如脾之积结块偏右、板痛上下不通、少腹结块（血蛊），脉沉紧而细，示阴寒盘踞、气血凝滞成积。"}, {"name": "主寒凝瘀血", "desc": "细为血少，紧为寒凝，沉为在里，寒凝血瘀则脉沉细紧。原文小产后瘀血未尽，误用凉药，血为寒凝，少腹结块、腹胀痛，脉沉细紧按之坚硬而长，示寒凝瘀结。"}, {"name": "主寒伤血络", "desc": "沉细紧示中焦虚寒，气不摄血。原文咳嗽痰秽咯血已多而吸短，断为‘中寒，气不摄血’，因寒凝于里，气失统摄，血不循经，故脉沉细紧，治以温中摄血。"}, {"name": "主寒盛阳衰", "desc": "沉细为阳虚，紧为寒盛，合示阴寒内盛、阳气衰微。原文见汗出沾衣、面赤、下利、厥冷等少阴证全，或阳证阴脉，脉沉细紧，皆因寒邪深陷，真阳衰惫，故当急扶阳。"}], "n": {"主里寒": 3, "主寒凝积滞": 4, "主寒凝瘀血": 1, "主寒伤血络": 1, "主寒盛阳衰": 7}, "a": {"10439": "主寒凝积滞", "10855": "主寒凝积滞", "11776": "主寒伤血络", "13659": "主寒凝积滞", "14778": "主寒凝积滞", "15675": "主里寒", "16099": "主寒盛阳衰", "16108": "主寒盛阳衰", "16109": "主寒盛阳衰", "16113": "主寒盛阳衰", "16118": "主寒盛阳衰", "16120": "主寒盛阳衰", "16204": "主里寒", "16231": "主里寒", "16232": "主寒凝瘀血", "21673": "主寒盛阳衰"}, "t": 16, "np": 0}, "c:数+浮+动": {"o": "浮动数脉总起来主风、热、虚、痛及阳动不宁之病机。浮为风、为虚阳上浮；数为热、为虚；动为痛、为阳动、为阴阳相搏。其证候谱较广：在外感病中，主太阳表邪未解、风热袭表，症见头痛发热、恶寒盗汗；若误下则热陷成结胸，或湿热郁蒸发黄。在内伤病中，主肝肾阴亏、水不涵木、肝风暴动，虚阳上浮，症见齿疼舌赤、精浊、偏瘫舌强等。各类之间以“阳热浮动”为共同基础：表证为外风引动，内伤为虚阳化风，误治则热陷邪结，发黄则湿热郁蒸，皆不离浮、数、动三象所反映的阳热亢动与正虚不摄。", "c": [{"name": "主虚阳上浮", "desc": "浮数动亦见于阴亏于下、虚阳上浮之证。原文“阴亏火升，时患鼻渊，脑热也。脉浮数而动”，浮为虚阳上浮，数为火，动为阴阳相搏，非表邪所致，乃肝肾阴亏、虚火升腾之象。"}, {"name": "主肝风暴动", "desc": "脉浮数动可因肝肾两虚、水不涵木、肝风暴动而致。原文“浮为阳浮，数为热，动为阳动”，症见齿疼舌赤、精浊、卒然右偏肢痿、舌强口喁语蹇，属河间“肝肾气厥”之证，虚阳化风内动。"}, {"name": "主热陷结胸", "desc": "表证误下，动数变迟，阳气内陷，邪热结于胸膈而成结胸。原文“医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气躁烦，心中懊憹，阳气内陷，心下因硬”，脉由动数转迟，反映热陷邪结之病机转归。"}, {"name": "主湿热发黄", "desc": "脉浮而动数，表邪未解而里已化热，误下后邪郁于上，若不成结胸，则但头汗出、小便不利、身必发黄。原文“若不结胸，但头汗出，小便不利，身必发黄”，说明湿热郁蒸、气机不畅，脉浮数动示表热与里湿相合。"}], "n": {"主虚阳上浮": 1, "主肝风暴动": 3, "主热陷结胸": 6, "主湿热发黄": 1}, "a": {"5703": "主肝风暴动", "7027": "主虚阳上浮", "10577": "主肝风暴动", "17918": "主肝风暴动", "18893": "主热陷结胸", "18894": "主热陷结胸", "20010": "主热陷结胸", "20843": "主热陷结胸", "21924": "主热陷结胸", "22961": "主湿热发黄", "22971": "主热陷结胸"}, "t": 11, "np": 0}, "pc:右+滑+洪": {"o": "右·滑洪脉总属实证、热证，以痰热壅盛为核心病机。洪为阳盛火炎，滑为痰湿内聚，右部候肺、脾、胃，故其主病多集中在肺胃中上二焦。归纳其类：一主痰热壅盛，为最根本者，痰热可流滞血海、蒙蔽心窍、上灼清窍；二主实热积滞，洪滑有力示邪实内结，常见腑实便闭、癥块拒按；三主暑热挟痰，暑邪薄肺，挟痰阻遏气机；四主痰火蒙心，痰火扰心则神昏狂躁；五主气郁食积，洪滑兼弦，痰食气郁交阻；六主肺胃实痰，右寸关洪滑直接对应肺胃痰积；七主肝胃热盛，洪滑兼弦硬，为肝胃火升、冲气上逆。诸类之间，以痰热为共同基础，或兼积滞、或兼暑邪、或兼气郁、或兼肝火，然皆不离洪滑主实主热之本质。脉症合参，右滑洪脉提示邪气壅盛，治当清化痰热、通降积滞，忌用温补滋腻。", "c": [{"name": "主痰热壅盛", "desc": "洪滑脉象中，洪为热盛，滑为痰聚，合之主痰热内壅。原文多段如、等均以右关洪滑为痰热壅滞中焦，症见昏冒、咬牙乱语、痰迷心窍；右寸关洪滑断为肺经痰火，见鼻塞、衄血、痰核。痰热可流滞血海、蒙蔽心窍、上灼清窍，脉症相合。"}, {"name": "主实热积滞", "desc": "洪滑有力主实热内结、积滞不通。如右关洪滑、两尺有力，为痰热结于胁下，症见右胁块起疼痛拒按、便结；右洪滑左弦数，为阳明腑实，见右手足不遂、舌謇、面赤便秘。洪滑示邪实热盛，积滞壅塞，故治以攻下通滞。"}, {"name": "主暑热挟痰", "desc": "右脉洪滑常见于暑热内盛、挟痰壅肺之证。如、妊妇患疟，右脉洪滑，断为伏暑，暑热内盛而胎未损；右脉洪滑而口渴，为暑邪薄肺，挟素有之痰阻遏治节，致疹不能达。洪主热盛，滑主痰壅，暑热与痰相合为病。"}, {"name": "主痰火蒙心", "desc": "右脉洪滑可主痰火壅盛、蒙蔽心包，致神志异常。如、朱大镛新婚后神呆目瞪、言语失伦、善饥善怒、骂詈如狂，右脉洪滑，断为痰火蒙蔽心包，用礞石滚痰丸而愈。洪为阳盛火炎，滑为痰聚，痰火扰心则狂躁神昏。"}, {"name": "主气郁食积", "desc": "右寸关洪滑兼左弦，主气郁食积化热、痰食壅滞中焦。如、暑月患痢，右寸关洪滑，左脉弦，断为气郁食积痢，症见小腹窘迫、胸膈膨胀、口舌焦渴。洪滑主痰热食积，弦主气郁，故先以木香槟榔丸开下。"}, {"name": "主肺胃实痰", "desc": "右寸关洪滑专候肺胃，主肺胃实痰壅盛。如明言“右寸洪滑，肺有实痰”；、右关洪滑主胃中痰积，见咳喘吐痰、胸胀、便下紫黑血。洪滑为实痰热壅于肺胃，肺失肃降，胃失和降，故咳喘胀满。"}, {"name": "主肝胃热盛", "desc": "右洪滑兼左弦硬而长，主肝胃热盛、冲气上逆。如温病热入阳明，右部洪滑而长，左部弦硬而长，症见表里壮热、嗜饮凉水、痰涎上泛、呃逆哕气、两胁作胀。洪滑主阳明胃热，弦硬主肝火冲气，合为肝胃热盛、痰热上壅。"}], "n": {"主痰热壅盛": 3, "主实热积滞": 3, "主暑热挟痰": 6, "主痰火蒙心": 10, "主气郁食积": 2, "主肺胃实痰": 5, "主肝胃热盛": 1}, "a": {"3622": "主痰火蒙心", "4027": "主痰火蒙心", "4232": "主实热积滞", "4328": "主痰火蒙心", "6014": "主痰火蒙心", "6023": "主肺胃实痰", "6079": "主气郁食积", "6133": "主实热积滞", "6225": "主肺胃实痰", "6308": "主痰火蒙心", "6317": "主肺胃实痰", "6373": "主气郁食积", "6428": "主实热积滞", "6520": "主肺胃实痰", "13142": "主暑热挟痰", "13181": "主痰火蒙心", "13228": "主暑热挟痰", "13352": "主痰火蒙心", "13935": "主痰火蒙心", "14083": "主暑热挟痰", "14100": "主痰热壅盛", "14108": "主暑热挟痰", "14204": "主痰火蒙心", "14377": "主暑热挟痰", "14403": "主暑热挟痰", "14501": "主痰火蒙心", "18257": "主痰热壅盛", "20695": "主痰热壅盛", "20711": "主肝胃热盛", "24699": "主肺胃实痰"}, "t": 30, "np": 0}, "pc:关+滑+洪": {"o": "关·滑洪脉总以实热痰浊壅盛为核心病机，洪为热盛，滑为痰聚，合而主痰热、食积、积滞等有余之证。其病位广泛，可在中焦脾胃、上焦心肺、肝胆及血海。痰热壅盛者，脉多洪滑有力，症见吐痰、胸胀、嘈杂、痰核；食积内停者，寸关洪滑而尺沉伏，症见倒饱、腹胀、泻而不畅；实热积滞者，洪滑鼓指，腹大坚满、胁块疼痛；上焦热盛者，关前洪滑，烦热、衄血、呕恶；上盛下虚者，关前洪滑而尺弱，虚阳上浮；痰火流滞血海者，右关洪滑、左寸洪数、两尺洪大，经乱昏冒。诸类之间，以痰热实积为共同基础，或兼气郁，或兼血瘀，或兼下虚，然总属邪实有余之候，治多从清化痰热、攻下积滞、条达郁火入手。", "c": [{"name": "主痰热壅盛", "desc": "洪滑脉象为实热与痰浊相合之征，原文多段以洪滑主痰热壅盛。如右关洪滑主胃中痰热，左寸关洪滑主肝胆郁火与胃中胶痰，右寸关洪滑主肺经痰火。痰火胶结，壅滞脏腑，故脉见洪滑有力，症见吐痰、胸胀、嘈杂、痰核等。"}, {"name": "主食积内停", "desc": "洪滑脉亦主食积痰饮内停肠胃。原文载两手寸关洪滑、两尺沉伏，断为肠胃中有食积痰饮，症见五更倒饱、腹常作胀、泻后不畅。洪滑主中上二焦痰食壅盛，沉伏示下焦积滞内闭，故脉症合参，主积滞内停之病机。"}, {"name": "主实热积滞", "desc": "洪滑鼓指有力，为有余之候，主实热积滞壅盛。如两关洪滑鼓指，腹大如斗、坚如石、小水不通，断为食冷积滞酿成鼓胀；右关洪滑、两尺有力，右胁块起疼痛拒按，为痰热结于胁下。洪滑有力示邪气壅盛，实热积滞内结。"}, {"name": "主上焦热盛", "desc": "关前洪滑主上焦热盛，心肺热壅。原文多段以关前洪滑异常，症见上焦烦热、恶心呕吐、鼻衄甚剧、头目不清、舌干无津。洪为热盛，滑为痰热内壅，关前候上焦，故主上焦痰热壅盛，火性炎上，迫血妄行则衄，灼津则口渴便燥。"}, {"name": "主上盛下虚", "desc": "关前洪滑而两尺无力或不任重按，主上盛下虚之证。原文载关前洪滑、两尺无力，为上焦热盛而下焦虚寒；关前洪滑、两尺不任重按，为下元虚损、虚阳上浮。洪滑见于关前示上焦痰热壅盛，尺弱示下焦虚损，合为上下虚实错杂之病机。"}, {"name": "主痰火流滞血海", "desc": "右关洪滑、左寸洪数、两尺洪大，主浊痰流滞血海。原文载经水不调，误服安胎之剂，致经水大行、昏冒乱语、咬牙口噤，断为浊痰流滞血海，痰迷心窍。洪滑数大皆痰火壅盛之象，痰热流滞血海，扰乱心神，故主痰火流滞血海之病机。"}], "n": {"主痰热壅盛": 6, "主食积内停": 5, "主实热积滞": 4, "主上焦热盛": 3, "主上盛下虚": 3, "主痰火流滞血海": 4}, "a": {"3447": "主食积内停", "3622": "主痰热壅盛", "4027": "主痰火流滞血海", "4232": "主实热积滞", "4328": "主痰火流滞血海", "6014": "主痰火流滞血海", "6023": "主痰热壅盛", "6025": "主食积内停", "6079": "主食积内停", "6125": "主实热积滞", "6133": "主实热积滞", "6166": "主痰热壅盛", "6225": "主上焦热盛", "6308": "主痰火流滞血海", "6317": "主痰热壅盛", "6319": "主食积内停", "6373": "主食积内停", "6428": "主实热积滞", "6461": "主痰热壅盛", "6520": "主上焦热盛", "19725": "主上盛下虚", "19846": "主上焦热盛", "19862": "主痰热壅盛", "19896": "主上盛下虚", "20259": "主上盛下虚"}, "t": 25, "np": 0}, "c:数+缓": {"o": "数缓脉总以数脉主热、缓脉主退为纲，所主病机涵盖实热、虚火、湿滞、郁火及邪退正复五类。数脉为热象，缓则示热势渐减或湿滞为患。实热者，数而有力，见于暑热内蕴、肠胃热结；虚火者，数而无力或细数，见于阴虚火旺、相火不潜；湿滞者，数缓并见而兼湿象，见于湿郁化热或寒湿下注；郁火者，数中带缓而兼气郁，见于木火内扰、气机不畅；邪退正复者，数脉转缓为热退胃和、阴复邪解之佳兆。诸类之间，以“数”为热之共性，以“缓”为势减或湿滞之异，临证须参脉之有力无力、兼脉及症候，辨其虚实寒热。", "c": [{"name": "主热", "desc": "数脉主热，缓为热势渐退之象。原文多见“脉数较缓”“脉数渐缓”“脉数转缓”，皆示火热渐退、邪热渐解。如“脉数较缓”示火热渐退；“脉数”主暑热内蕴；“脉数逾六至”为热盛之征。"}, {"name": "主虚火", "desc": "数而缓或细数无力，主阴虚火旺、虚火内动。原文如“脉数稍缓”而“龙相之火尚未安静”，主肾水不足、相火不潜；“脉细数无力”为肾阴亏损、虚火刑金；“浮数而细”为阴分太亏。"}, {"name": "主湿滞", "desc": "缓脉主湿，数缓并见示湿郁化热或湿滞未清。原文“左数右缓”为湿邪痹阻、郁而化热；“脉当数而反缓”为湿为寒、脾阳不足；“脉数转缓”而“滑泄频来”为阴虚挟湿、湿浊未清。"}, {"name": "主邪退正复", "desc": "数脉转缓多示邪热渐退、胃气渐和、正气来复之佳兆。原文“脉数已缓”为邪解之象；“脉数转缓”为邪退胃和；“脉数较缓”为腑中蒸变乍平、里热已减；“脉缓不数”为热退阴复之转机。"}, {"name": "主郁火", "desc": "数脉主郁热内扰，缓为郁火渐平之象。原文“脉数亦缓”示木乘土位、化火伤阴之势已退；“脉数较缓”为清泄后木火稍平，但余威尚盛、气化为火；“右之数虽缓”而左弦劲未平，主肝郁血滞。"}], "n": {"主热": 3, "主虚火": 5, "主湿滞": 3, "主邪退正复": 8, "主郁火": 2}, "a": {"350": "主虚火", "372": "主邪退正复", "681": "主热", "732": "主邪退正复", "2136": "主邪退正复", "3618": "主邪退正复", "4939": "主湿滞", "5346": "主邪退正复", "7448": "主虚火", "7659": "主郁火", "7956": "主邪退正复", "8056": "主湿滞", "10922": "主邪退正复", "11241": "主邪退正复", "12760": "主郁火", "15491": "主虚火", "15885": "主虚火", "16357": "主湿滞", "20061": "主热", "20133": "主热", "20192": "主虚火"}, "t": 21, "np": 0}, "pe:右+细": {"o": "右·细脉总属虚象，以气血阴阳亏虚为共同基础，右脉候脾肺，故尤重脾肺气虚。细为脉道不充，主阴血亏少、气弱不充；兼数则虚热内扰，兼濡软则脾虚湿滞，兼弦则肝脾不和，兼滑数弦则正虚邪恋、痰热积滞。诸类之中，虚为根本：气虚则推动无力，血虚则脉道不充，阴虚则虚火内生，阳虚则寒湿内停。虚久则易夹滞，湿郁化热，肝木乘脾，痰邪胶结，故见虚中夹实、本虚标实之候。各段原文或从右寸主肺气不足，或从右关主中气虚弱，或从右尺主膀胱气弱，皆以右部候气、候脾肺为纲，细脉所主病机虽繁，总不离正虚为本、邪恋为标，而脾肺气虚、阴血亏耗尤为关键。", "c": [{"name": "主气虚", "desc": "右脉候脾肺，细为脉道不充，主气弱。原文见右脉细而左弦，示中气久虚、肝气横逆；右寸脉细主肺气不足；右关脉弱、右尺脉细主中气、膀胱气弱。细弱并见则脾肺气虚，运化无力。"}, {"name": "主血虚阴亏", "desc": "细为阴血亏少，脉道不充。原文见右细左搏，颧赤气喘汗泄，为阴衰阳冒；左右细涓近数，尺部左软右细，属真阴失固；右细耎无力兼左寸涩，为心血不足。皆阴血亏虚之征。"}, {"name": "主脾虚湿滞", "desc": "右脉主脾，细主虚，濡软主湿。原文见右细濡、右细耎，主脾虚湿盛、湿浊内停；右细滞示中焦湿滞、气机不畅；右细软无神为伏痰与邪胶黏，正气不能流通。脾虚运化失职，湿浊内生。"}, {"name": "主虚中夹热", "desc": "细为阴伤，数为虚热。原文见右脉细数，脾脉弦滑，为酒肉积热伤脾、郁热伤阴；右细涓近数，为虚热内扰；冬温伏热，右细左搏，为阴衰阳浮。正虚为本，虚火为标，细数并见。"}, {"name": "主肝脾不和", "desc": "右细主中气虚弱，左弦主肝气横逆。原文见右脉细、左脉弦，大便溏、饮食少，为肝逆犯脾、土虚木旺；右细滞左弦，肝逆犯胃，脘格呕恶。右细示脾虚，左弦示肝郁，木乘土位。"}, {"name": "主正虚邪恋", "desc": "细主正虚，兼弦滑数等为邪恋。原文见右脉细软无神，左弦大有力，伏痰与邪胶黏不散，结胸；右细耎，左弦细，素体虚肥多湿痰，感冒后脾肾两虚、湿阻中宫。久病正虚，痰湿余邪未净。"}], "n": {"主气虚": 4, "主血虚阴亏": 4, "主脾虚湿滞": 3, "主虚中夹热": 2, "主肝脾不和": 4, "主正虚邪恋": 1}, "a": {"3843": "主虚中夹热", "4609": "主血虚阴亏", "4951": "主血虚阴亏", "5957": "主肝脾不和", "9144": "主血虚阴亏", "9658": "主肝脾不和", "10770": "主肝脾不和", "10913": "主气虚", "11226": "主正虚邪恋", "14693": "主肝脾不和", "15212": "主虚中夹热", "15773": "主脾虚湿滞", "15782": "主脾虚湿滞", "15942": "主血虚阴亏", "16886": "主脾虚湿滞", "17233": "主气虚", "24751": "主气虚", "25096": "主气虚"}, "t": 18, "np": 0}, "pe:右+浮": {"o": "右浮脉总以浮主表、主风为纲，右脉候肺、脾、阳明气分，故其病机多围绕肺卫与气分展开。归纳其要：一为外感风邪或风热、风寒、风湿客表，脉多浮而兼数、紧、濡；二为风水或湿郁三焦，浮而兼弦滑；三为虚阳外浮，浮而无力或不敛，主气虚、阳虚、气阴两伤；四为三阳合病，浮弦实并见；五为肺痹积气，浮而喘。诸类之中，外感表证最为常见，因浮脉本主肌表，邪客则气血趋外；兼脉不同则病性各异：浮数多热，浮紧多寒，浮濡多湿，浮大有力多实热，浮而无力多虚。虚证之浮，乃正气不足、脉气外浮，与表证之浮有力者迥别。此外，右浮亦可见于内伤杂病兼夹外感，如肝脾不和兼风、虚损兼表等，当结合分部与兼脉细辨。", "c": [{"name": "主表感风", "desc": "浮脉主表，右脉候肺卫，故外感风邪初客肌表多见右浮。原文如案39“右脉略浮”因兼感风、咳呛有痰；20537“右脉犹浮”示表证未罢；20274“左右皆浮而有力”为外感之热。风邪在表，气血抗邪于外，故脉浮。"}, {"name": "主虚阳外浮", "desc": "浮而无力或浮而不敛，主气虚或阳虚，虚阳外浮。如10415“右寸浮而不敛”为阳虚阴亏、卫表不固，自汗厥逆；20557“右脉浮而无力”因病久气血虚弱；浮濡亦主脾肺气虚、气阴两伤。正气不足，脉气不能内守，故浮而无力。"}, {"name": "主风水/湿郁", "desc": "浮脉主风水或湿邪郁蒸。20527引《金匮》“风水脉浮”，因有汗受风、肿甚，断为风水；9009“左脉浮”为阴经受湿招风，风温之邪郁蒸三焦，湿重于风。风邪与水湿相合，郁于肌表或三焦，故脉浮。"}, {"name": "主三阳合病", "desc": "右脉浮而弦实，可主三阳合病。20080“左右脉皆弦，右脉尤弦而有力，重按甚实，关前且甚浮”，断为三阳合病：浮主太阳，弦主少阳，重按实主阳明。邪盛于表里之间，三经同病，故脉浮弦实并见。"}, {"name": "主肺痹积气", "desc": "浮而喘，主肺痹、积气在胸中。23081、23346引《五脏生成论》“白脉之至也，喘而浮，上虚下实，惊，有积气在胸中，喘而虚，名曰肺痹，寒热”。浮主上虚下实，肺气不降，积气内结，故脉浮而喘。"}, {"name": "色脉相参", "desc": "总论望色与切脉相合，以外知内，脉色相应则吉、相逆则病，非专论右浮之具体病机。"}], "n": {"主表感风": 11, "主虚阳外浮": 3, "主风水/湿郁": 2, "主三阳合病": 1, "主肺痹积气": 2, "色脉相参": 1}, "a": {"6752": "主表感风", "8501": "主虚阳外浮", "9009": "主风水/湿郁", "10415": "主虚阳外浮", "18621": "色脉相参", "20080": "主三阳合病", "20238": "主表感风", "20274": "主表感风", "20527": "主风水/湿郁", "20537": "主表感风", "20557": "主虚阳外浮", "20642": "主表感风", "23081": "主肺痹积气", "23346": "主肺痹积气", "23990": "主表感风", "24738": "主表感风", "25015": "主表感风", "25040": "主表感风", "25058": "主表感风", "25090": "主表感风"}, "t": 20, "np": 0}, "pe:关+浮": {"o": "关·浮脉总起来主风邪、热郁、虚阳浮越、气逆、表证及疮毒等病机。浮脉主表、主风、主阳热，关部候中焦肝胆脾胃，故关浮多反映风邪外袭、肝木劲急、中焦热郁气壅或虚阳上浮。各类之间相互关联：风邪外袭可引动肝风，肝郁气滞可化火生痰，痰热壅盛则关脉浮而气旺；热毒壅滞又可致疮疡肿痛，虚阳浮越则见关脉浮而兼细沉。总以邪气外浮、气机失调为核心，虚实寒热需结合兼脉及症状辨别。", "c": [{"name": "主风邪", "desc": "关脉浮主风邪外袭或风木之邪。原文如风泻脉多浮而弦，左关浮弦为风木之邪；风气霍乱左关浮为风木之邪，右关浮为土受木贼。浮主邪在表分，风性轻扬，故关浮应风邪客于肌表或肝木乘脾。"}, {"name": "主热郁", "desc": "关脉浮主中焦阳热郁结。原文心下痞按之濡，其脉关上浮，为无形邪热痞塞中焦气分；又两手关脉独浮，气大旺，为少阳阳明热毒未除，肝郁化火。浮为阳热之象，热郁气壅则关脉浮。"}, {"name": "主虚阳浮越", "desc": "关脉浮主脏气虚寒、虚阳上浮。原文藏结寸脉浮、关脉小细沉紧，寸浮示阳气浮越于上，关小细沉紧示脏气虚寒、阴寒内结；又左尺脉浮主肝肾阴虚，虚火上炎。浮而无力或兼细沉，为虚阳不潜之象。"}, {"name": "主气逆", "desc": "关脉浮主肝气上逆、气机失调。原文左脉关部复浮，为肝经郁热再起、气火复动；左关之浮已去，六部近和平，说明肝木犯胃之气逆已平。浮为气机上浮，关候肝胆，故关浮主肝气上逆、气火复动。"}, {"name": "主表证", "desc": "关脉浮主外感表证、邪在肌表。原文太阳中风阳浮而阴弱，浮脉见于关前，为风邪袭表、卫阳浮越；又关前且甚浮，断为三阳合病，邪盛于表里之间。浮主表，关前浮甚为表邪未解之征。"}, {"name": "主疮毒", "desc": "关脉浮主热毒壅滞、疮疡未净。原文左脉关部复浮，疮口痛甚，为热毒壅滞、气血不通，肝火复动；又发背脉浮者，示元气虚实不同，灸法可随手取效。浮为邪气外浮、热毒未净之象。"}], "n": {"主风邪": 3, "主热郁": 7, "主虚阳浮越": 3, "主气逆": 1, "主表证": 2, "主疮毒": 3}, "a": {"5675": "主疮毒", "5676": "主疮毒", "18891": "主虚阳浮越", "18904": "主热郁", "18905": "主热郁", "19358": "主风邪", "19977": "主表证", "20019": "主热郁", "20080": "主表证", "20399": "主虚阳浮越", "20735": "主气逆", "21922": "主虚阳浮越", "22934": "主热郁", "22970": "主热郁", "23990": "主疮毒", "24211": "主热郁", "24738": "主热郁", "25015": "主风邪", "25040": "主风邪"}, "t": 19, "np": 0}, "pe:右+微": {"o": "右微脉总属阳气衰微、正气不足之象，然其所主病机广泛，涉及多个脏腑及虚实夹杂之证。微脉本为气血鼓动无力，右寸候肺、右关候脾，故右微多主脾肺气虚、中阳衰微；若与阴血亏虚并见，则为阴阳两虚；若尺部沉伏而微，则主肾虚火不归原、虚阳浮游；若与实脉并见，则示正虚邪实、阴阳逆乱；若微而难见、至数悬殊，则为祟凭乱常、神失所主；若寸关微见如水上浮麻，则为大气下陷、血脱气散之危候。各类之间，总以阳气虚衰为共同基础，或兼阴伤，或兼火浮，或兼邪实，或兼气陷，或兼神乱，然皆不离正虚一端，故右微脉总以虚候为多，然亦须结合部位、兼脉及证候，辨其虚实寒热之所在。", "c": [{"name": "主阳气虚衰", "desc": "右微脉为阳气衰微之象。原文如痢久伤阴案见右微，断为阳气不肯下交于阴；中宫阳气欲寂案左脉微，主中阳衰微；左脉微而无神案，微为阳气衰微，无神为胃气将败。皆因阳气不足，鼓动无力，故脉微。"}, {"name": "主阴阳两虚", "desc": "右微脉可见于阴阳两伤、气血交亏之证。如痢久伤阴案右微与泻血、汗泄、不寐并见，为阴阳两伤、脏气耗散；右微已振、左脉稍濡案，微濡并见示气血交亏、阴阳两虚；虚劳案右寸微、关虚小、尺软，左弦细，为阴阳两亏之征。"}, {"name": "主肾虚火浮", "desc": "右微无力而右尺伏而不起，主肾虚火不归原。原文断为“尺脉沉伏者，肾虚也”，日夜上下循环之热为“肾火之浮游”，子时足底大热为火归就下。脉微为阳气不足，尺伏为肾虚，故主肾虚火浮、虚阳游走。"}, {"name": "主正虚邪实", "desc": "右微与实脉并见，示正虚邪实。如左脉微而无神、右脉数实，微为阳气衰微，数实主里热结聚，十余日不大解，颇有下证，但烦躁不宁，未敢轻下；伏暑似疟案左洪大数实、右阳微，为阴阳逆乱、暑热内伏而气分不足。"}, {"name": "主气陷血脱", "desc": "右寸关微见如水上浮麻，左部脉皆不见，为大气下陷、血脱气散之危候。原文骤得下血甚剧，气息奄奄，脉微见不分至数，急用黄耆升补大气，脉虽出而微细异常，血仍不止，呼气不能外出，欲大便，皆大气下陷之征。"}, {"name": "主脾肺气虚", "desc": "右寸脉微主肺气有损，右关脉濡主中气不足，寸关皆涩主脾肺俱虚。气虚咳嗽之脉，右寸微为肺气有损；右脉涩、左脉微，饮食不能健运、嗳呕溏泄，为中宫阳气欲寂、脾胃阳衰、运化无权。"}, {"name": "主祟凭乱常", "desc": "两手脉如出两人，左脉七至大而无伦，右脉三至微而难见，至数悬殊、大小迥异，非脏腑常度，原文称为祟凭之脉。数大者阳扰于上，微而难见者正夺于下，阴阳不相维系，神失所主，故昏晕狂言、喃喃不休，为恶中之候。"}, {"name": "色脉相参", "desc": "指诊病须望色与切脉内外合参，以五脏应五色、五脉合五脏，察其应与不应、顺与不顺，方能断病邪逆顺、万举万全。"}], "n": {"主阳气虚衰": 3, "主阴阳两虚": 2, "主肾虚火浮": 2, "主正虚邪实": 2, "主气陷血脱": 1, "主脾肺气虚": 1, "主祟凭乱常": 1, "色脉相参": 1}, "a": {"2154": "主阳气虚衰", "2155": "主阴阳两虚", "3292": "主祟凭乱常", "3606": "主肾虚火浮", "4228": "主肾虚火浮", "5020": "主阳气虚衰", "5203": "主正虚邪实", "11587": "主阳气虚衰", "15919": "主阴阳两虚", "18564": "主正虚邪实", "18621": "色脉相参", "19812": "主气陷血脱", "24710": "主脾肺气虚"}, "t": 13, "np": 0}, "c:数+细+大+沉+浮": {"o": "沉细数浮大脉总属虚实夹杂、阴阳格拒之象。沉细主阴寒内盛、阳气虚衰，数主虚阳躁动或热邪内扰，浮大主虚阳外浮无根。其病机核心在于下焦虚寒、元阳不足，虚阳不能潜藏而上浮，形成上焦燥热与下焦虚寒并存的戴阳证。原文明确指出，若脉沉细而数或浮大而数，断不可用通脉四逆汤，因非单纯少阴沉细之寒化证，而是虚阳上浮、寒热错杂之候。案例中关前洪滑数、两尺无力，误用凉药后关前脉倍大、数至七至，更显虚阳浮越、上焦燥热与下焦虚寒之对立。三类病机相互关联：下焦虚寒为根本，虚阳浮越为病势，上焦燥热为标象，共同构成戴阳证脉象的复杂格局。", "c": [{"name": "主虚阳浮越", "desc": "脉沉细数或浮大数，沉细示阴寒内盛、阳气虚衰，数示虚阳躁动，浮大示虚阳外浮无根。原文强调戴阳证中此脉断不可用通脉四逆汤，因非单纯少阴沉细，而是虚阳上浮、下元虚寒之象。"}], "n": {"主虚阳浮越": 1}, "a": {"20259": "主虚阳浮越"}, "t": 1, "np": 0}, "c:微+紧+动+芤": {"o": "芤动微紧脉总起来主虚劳失精、阴阳两虚、虚阳不潜之病机。其核心为精血亏虚、阳气扰动、阴阳失交。各类病机相互关联：失精梦交是精血亏虚、虚阳扰动的直接表现；虚寒精亏是精血不足、阳气不能温养所致；阴阳两虚是失精日久、阴损及阳的必然转归；亡阳惊狂是虚阳外越、神不守舍的变证；亡血则是阴血亏耗、阳气逼血外出的结果。诸类皆以虚为本，或兼寒、或兼惊、或兼亡血，总属虚劳范畴，治当调和阴阳、固摄精气。", "c": [{"name": "主失精梦交", "desc": "芤动微紧脉主男子失精、女子梦交。原文多次明言“脉得诸芤动微紧，男子失精，女子梦交”。芤主精血虚，动主阳扰，微紧主虚寒内结，精血亏虚而虚阳扰动，阴阳失交，故精关不固、梦交失精。"}, {"name": "主阴阳两虚", "desc": "芤动微紧与极虚芤迟并见，提示阴阳两虚。原文“脉极虚芤迟，为清谷亡血失精”，虚为精气亏，芤为血少，迟为阳衰；芤动微紧则阴精亏而虚阳扰动。两者皆主虚劳失精、阴阳两虚、虚阳不潜之病机。"}, {"name": "主亡阳惊狂", "desc": "原文引伤寒脉浮、火迫劫之亡阳，又及脉芤动微紧。浮为邪在表，火迫津伤则脉芤，动主惊，微紧主虚寒。惊怖火邪致心无所依、神无所归，故脉浮而芤动微紧，主亡阳惊狂之机。"}, {"name": "主亡血", "desc": "芤脉主亡血，原文以“脉得诸芤动微紧”与“脉极虚芤迟”并举，芤主亡血，动主阴阳相搏，微紧主虚寒收引。芤动微紧并见，说明阴不交阳、阳气四射逼血外出，故主亡血，其同在亡血，其异在少腹弦急等症。"}], "n": {"主失精梦交": 2, "主阴阳两虚": 2, "主亡阳惊狂": 1, "主亡血": 1}, "a": {"22124": "主失精梦交", "22863": "主失精梦交", "25279": "主阴阳两虚", "25280": "主阴阳两虚", "25787": "主亡阳惊狂", "25832": "主亡血"}, "t": 6, "np": 0}, "c:数+弦+沉+虚": {"o": "虚弦沉数脉总起来主虚实夹杂之证，以虚、惊、热、痰滞四类病机为核心。虚为气馁，惊为神扰，热为郁热内停，痰滞为饮停中脘，四者相互交织：因大劳致虚，因惊致弦，因饮停化热而沉数。原文治以补虚清热、导去痰滞，正合此脉机。虚与惊常并见（虚弦），热与痰滞多相因（沉数），故临床须虚实兼顾，不可偏执。", "c": [{"name": "主虚", "desc": "脉虚弦沉数中“虚”为气馁不足，原文“虚为气馁”“虚弦是惊”并见，且治以参、术补虚，旬日未效因“虚未回”，故虚象主正气亏虚，尤以气虚为主。"}], "n": {"主虚": 2}, "a": {"3771": "主虚", "18719": "主虚"}, "t": 2, "np": 0}, "c:数+弦+洪+涩": {"o": "弦洪涩数脉总起来主木火亢盛、阴伤血滞、肝阳上僭与正气溃败。弦洪数主木火亢盛，为病之标；涩主阴伤血滞，为热灼日久、阴液耗损之果；上溢示肝阳上僭，为木火挟痰上逆之势；而右脉软滑大无神，则示胃气已败、正气溃败，为病之本。四类病机相互交织：木火亢盛则灼阴耗血，阴伤血滞则助火生痰，肝阳上僭则气血上冲，终致胃气衰败、正气溃散。此脉见于高年滞下危证，脉证俱逆，故预后不良。", "c": [{"name": "主木火亢盛", "desc": "脉弦洪数，弦为肝木，洪数为火热，合则木火亢盛。原文谓‘弦洪为木火亢盛’，‘弦洪数主木火亢盛’，且见唇舌紫、痰中带血、溲热如沸等症，皆木火挟痰上逆之象。"}], "n": {"主木火亢盛": 2}, "a": {"13213": "主木火亢盛", "13922": "主木火亢盛"}, "t": 2, "np": 0}, "c:微+弱+缓+迟": {"o": "微弱迟缓脉总主阳气衰微、气血虚衰之证。其脉象微弱，为阳气无力鼓动；迟缓，为脉气壅滞或从容不迫。所主病机主要有二：一为阳衰寒饮，心阳薄弱，寒饮凌心，治宜温阳化饮；二为气血虚衰，多见于失血之后，脉证相符则生，若脉转急疾则预后不良。二者皆属虚候，但前者偏于阳虚寒盛，后者偏于气血亏虚，临证当结合具体脉症辨析。", "c": [{"name": "主阳衰寒饮", "desc": "脉微弱迟缓，因阳气衰微，鼓动无力，故脉微弱；寒饮内盛，脉气壅滞，故迟缓。原文谓心脏本体之阳薄弱，胃中寒饮溢于膈上，凌逼心阳，致心脏渐欲麻痹，脉象异常微细，脉搏异常迟缓，治以理饮汤温阳化饮，正合此机。"}], "n": {"主阳衰寒饮": 2}, "a": {"20186": "主阳衰寒饮", "21149": "主阳衰寒饮"}, "t": 2, "np": 0}, "pc:左+数+弦+细+虚": {"o": "左数弦细虚脉总属阴阳两虚、虚阳上浮之候。其脉左弦细为肝肾阴虚、阳不潜藏，右虚数为脾肺气虚、虚阳浮越，合之则见阴阳两损、下焦阴不上承、上焦虚阳不降。根本在于肝肾根蒂不固，冲脉震动，诸脉俱逆，故见眩晕、盗汗、咳嗽喘促等症。此脉所主非实热、非单纯肝病，乃虚阳上冒、气阴两伤之复杂病机。各类之间相互关联：阴虚则阳浮，气虚则阳越，阴阳两损则冲逆震动，形成下虚上实、本虚标热之格局。治当固摄肝肾、潜降虚阳，忌用泄气伤阴之品。", "c": [{"name": "主阴虚阳浮", "desc": "脉左弦细，为肝肾阴虚、阳不潜藏之象。原文谓'左弦细为肝肾阴虚、阳不潜藏'，又见眩晕、盗汗，乃虚阳上冒所致。阴亏于下，阳浮于上，故脉弦细而数，主阴虚不能制阳，虚阳上越。"}], "n": {"主阴虚阳浮": 1}, "a": {"319": "主阴虚阳浮"}, "t": 1, "np": 0}, "pc:左+数+弦+滑+紧": {"o": "左数弦滑紧脉，总起来主温疫火郁之候。其脉象数、滑、弦、紧并见，反映邪火炽盛与郁结并存：滑数主温疫之邪化火，充斥内外，蔓延三焦，故见发热、丹赤、痧点、舌红；弦紧主邪势鸱张，郁于少阳，故见咽痛连颈肿。火郁相合，邪势正盛，有内窜心包、致神昏发痉之虞。三类病机中，温疫化火为病之本，邪郁少阳为火郁之枢，火窜心包为火盛之变，层层递进，总属温疫火毒壅盛、三焦蔓延之实证。", "c": [{"name": "主温疫化火", "desc": "右脉滑数，为温疫之邪从内而发，一发便化为火，充斥内外，蔓延三焦。原文见发热咽痛、热势甚炽、遍身丹赤、痧点连片，舌红边尖满布赤点，皆火邪炽盛之象，故滑数主温疫化火。"}], "n": {"主温疫化火": 1}, "a": {"7428": "主温疫化火"}, "t": 1, "np": 0}, "c:数+细+虚+濡": {"o": "濡细数虚脉总属虚象，以中气久虚、真阴亏损为根本。濡主气虚，细主阴亏，数主虚热，三象合见，示气阴两虚、虚热内生之候。中气虚弱则运化无力，纳谷运迟；胃虚气逆则客气上逆，噫嗳频作；真阴亏损则脉道不充而细，虚阳浮动而数。四类病机以“虚”为纲：气虚、阴亏为本，虚热为标，气逆为变。虚热由气阴两虚而生，气逆由中虚不运而致，标本相因，虚实错杂，然总不离中气与真阴两虚之本质。", "c": [{"name": "主气虚", "desc": "原文谓“濡为气虚”，濡脉浮软无力，主中气不足。中气久虚则运化无力，故见纳谷运迟、噫嗳上逆。脉濡与中虚证候相合，示气虚不运、客气上逆之机。"}], "n": {"主气虚": 1}, "a": {"8282": "主气虚"}, "t": 1, "np": 0}, "pc:左+数+浮+小+濡": {"o": "左·数浮小濡脉总属虚候，以气阴两伤为核心，兼涉虚热、脾肺气虚及暑湿未清。浮小为气虚阳浮，濡为阴伤湿滞，数为虚热内扰；右部尤不足，则脾肺之气亏甚。诸类相互关联：疟久截药伤正，致脾肺气虚，气不化津则阴伤，阴虚阳浮则生虚热，暑湿余邪留恋不去，故脉象浮小濡数并见。总言之，此脉主正虚邪恋、气阴耗伤之病机，虚多实少，治当益气养阴、清暑化湿，不可妄投截疟攻伐。", "c": [{"name": "主气阴两伤", "desc": "脉浮小而濡带数，浮小为气虚阳浮，濡为阴伤不敛，数为虚热内扰。原文谓'气阴两伤、虚热内扰'，且右脉尤不足，示脾肺之气亏耗，故主气阴两伤之病机。"}], "n": {"主气阴两伤": 1}, "a": {"15079": "主气阴两伤"}, "t": 1, "np": 0}, "c:细+沉+缓+迟": {"o": "沉细迟缓脉总起来主阳气衰微、阴寒内盛。沉细为阳气衰微，迟为脏寒，缓主中焦虚冷，三者相合，反映阳气不足、脏腑虚寒之病机。其具体可表现为中焦虚冷、阳虚寒盛，甚则阳气欲脱。原文见中脘胀痛、厥逆、汗多、食不喜进，脉沉细迟缓，乃阴寒内盛、阳气欲脱之危候。各类病机相互关联，均以阳气衰微为核心，中焦虚冷为常见表现，阳衰欲脱为危重转归。", "c": [{"name": "主阳虚寒盛", "desc": "沉细为阳气衰微，迟为脏寒，缓主中焦虚冷。原文脉息沉细迟缓，伴中脘胀痛、厥逆，乃阴寒内盛、阳气欲脱之兆，故主阳虚寒盛。"}], "n": {"主阳虚寒盛": 1}, "a": {"16008": "主阳虚寒盛"}, "t": 1, "np": 0}, "c:细+沉+涩+弱": {"o": "沉细弱涩脉总属阴寒凝滞、气血虚损之象。其脉沉主里，细弱主虚，涩主滞，合而示阴寒之邪凝滞于内，气血不足且运行不畅。原文以“阴滞于阳”概括其病机，与阳热之“浮洪弦数”相对，治当以热药温通。此脉又见于痈疽疮疡，因气血虚滞而肌肉难长、疮久未合，故中年后见虚弱脉象当予滋补，不可妄用驱毒利药。三类病机相互关联：阴寒凝滞可致气血不畅，气血虚损又加重凝滞，最终影响疮疡愈合，总以虚寒凝滞为要。", "c": [{"name": "主阴寒凝滞", "desc": "原文谓“阴滞于阳则脉沉细弱涩，为阴寒凝滞”，沉主里、细弱主虚、涩主滞，合而示阴寒之邪凝滞于阳分，气血不畅，故脉象沉细弱涩，治当以热药温通。"}], "n": {"主阴寒凝滞": 1}, "a": {"18703": "主阴寒凝滞"}, "t": 1, "np": 0}, "pc:左+细+滑+沉+疾": {"o": "左·细滑沉疾脉总起来以主热为核心，兼主气血偏颇与病在腑。沉细滑疾，疾数为热，滑为阳盛，沉细示热郁于里，故主里热或郁热；滑脉多血少气，细滑并见则血气分布不均，气分偏弱而血分偏盛；疾属数类，数脉在腑，故又主病在腑。三类之间以热为枢：热盛于腑则脉数疾，热郁于里则沉细，热扰血分则滑而血多气少。故临床见此脉，当以清解里热为主，兼顾气血之偏。", "c": [{"name": "主热", "desc": "原文明言“脉沉细滑疾者热”。沉细滑疾，数疾之象为热，滑为阳脉，主热盛；沉细则热郁于里，故沉细滑疾主里热或郁热。"}], "n": {"主热": 1}, "a": {"21801": "主热"}, "t": 1, "np": 0}, "c:数+滑+沉+紧": {"o": "沉紧滑数脉总起来主里实热结，兼有水饮结聚之变。沉主里，紧主痛，滑数主热实，故凡热邪内陷、与有形实邪结于胸腹，见舌干而渴、日晡潮热、胀满痛不可近者，脉当沉紧滑数。若水饮结聚，则热象不显而脉转沉涩，然其病位仍在里，故沉紧滑数亦可提示水结之可能。两类病机均以里实为共同基础，热结与水结为其具体分化，临证当结合兼症辨别。", "c": [{"name": "主里实热结", "desc": "脉沉紧滑数，沉主里，滑数主热，紧主痛。原文大陷胸汤证因汗下后热邪内陷，与有形实邪结于胸腹，故脉见沉紧滑数，伴舌干而渴、日晡潮热、胀满痛不可近，显系里实热结之征。"}], "n": {"主里实热结": 1}, "a": {"25513": "主里实热结"}, "t": 1, "np": 0}, "c:细+涩+迟": {"o": "迟细涩脉总起来主寒凝、气滞、血瘀与虚损相兼为病。迟主阳郁或阳衰，细主气少血虚，涩主气机壅滞或血瘀。三者相合，多示寒邪凝结、阳气不宣，或气机闭郁、肺金实而无声，或血虚兼瘀、血不归经。各案虽病位不同，或在心胸，或在肺金，或在肝血，但共同病机为寒、虚、滞、瘀交织，导致脉道不利、气血运行受阻。临床需结合部位与兼症，辨其寒凝、气闭、血瘀之侧重。", "c": [{"name": "主寒凝阳郁", "desc": "迟主阳郁不宣，细涩主寒凝血脉、气机不利。如案4心痛彻背，寒气结痹阳位，阳郁不宣，脉迟细涩，说明寒邪结于阳位，阳气不能流布，故脉道迟细而涩。"}, {"name": "主气滞闭郁", "desc": "涩主气机壅滞不畅，细为气少。如案8风寒郁肺，又食酸果收敛，咳嗽音闪，金实无声，脉迟细而涩，迟为寒凝，细为气少，涩主气机壅滞，正合寒邪与酸收相合、肺气闭郁之实。"}, {"name": "主血虚瘀滞", "desc": "迟为阳衰，细为血少，涩为血瘀。如案2经停三月，崩冲瘀块如拳，脉迟细涩，腹痛自汗面青，乃瘀血内阻，血不归经，肝无藏血，血去过多则气随血脱，此脉主肝血亏虚兼瘀滞。"}], "n": {"主寒凝阳郁": 1, "主气滞闭郁": 2, "主血虚瘀滞": 1}, "a": {"11698": "主寒凝阳郁", "11758": "主气滞闭郁", "11817": "主气滞闭郁", "11904": "主血虚瘀滞"}, "t": 4, "np": 0}, "c:大+和+平": {"o": "大和平脉总起来主正气未败、病势轻浅或向愈，但和平之中常藏病机。其主病机可分四类：邪退正复为向愈之兆；正虚邪陷为和平中见微弱有力，示邪陷正虚；水湿郁热为平和兼滑数，示湿郁微热；下焦不固为尺浮不实，示虚阳上冲。四类均以和平为底色，反映正气尚存，而兼脉揭示具体病机。和平脉非绝对无病，须结合兼象与部位判断，或为向愈，或为轻证，或为虚损，总以正气未大伤为前提。", "c": [{"name": "主邪退正复", "desc": "脉象由病脉转为和平，是邪气已退、正气渐复之佳兆。如第20481段药后脉大见和平，里热清、腑气通；第19493段邪陷正虚，经治后脉象和平乃邪退正复。和平脉在此反映疾病向愈、气机渐复。"}, {"name": "主正虚邪陷", "desc": "脉虽近和平，但兼见浮分微弱、重按似有力等，为邪陷于里、正气不足之象。如第19493段温病误用破气，邪陷已深，浮微示正虚，重按有力示邪陷，脉象和平中藏邪陷正虚之机。"}, {"name": "主水湿郁热", "desc": "脉象大致平和而微有滑数之象，为水湿内郁、兼有微热之征。如第19654段水肿证，平和示正气未败，滑数示水湿郁热，故用茅根汤清利而愈。和平中见滑数，主水湿郁热轻证。"}, {"name": "主下焦不固", "desc": "脉大致近和平，惟两尺稍浮、按之不实，为下焦气不固摄、虚阳挟热上冲之象。如第20434段气从下焦上冲，尺浮不实示下焦不藏，冲气上逆，脉虽和平而尺部独异，主下焦不固、冲气上逆。"}], "n": {"主邪退正复": 1, "主正虚邪陷": 1, "主水湿郁热": 1, "主下焦不固": 1}, "a": {"19493": "主正虚邪陷", "19654": "主水湿郁热", "20434": "主下焦不固", "20481": "主邪退正复"}, "t": 4, "np": 0}, "c:滑+浮+紧": {"o": "浮紧滑脉总起来主外寒束表、痰饮内搏，以及表寒里饮、痰热壅肺等复杂病机。浮紧为寒邪外束肌表，卫阳被遏；滑为痰湿内蕴，或痰浊瘀滞。三者相合，提示外寒引动内饮，表闭与里饮同病，症见寒热无汗、咳嗽气喘、难于平卧、痰秽如脓等。若兼胃有蕴热，则痰热交结，壅塞肺叶，发为肺痈。各类病机之间相互关联：外寒为诱因，痰饮为内因，表寒里饮是基本格局，痰热壅肺是进一步演变。脉象揭示邪实壅盛，非单一邪气为患，故治疗需外散表邪、内化痰饮，兼清郁热。", "c": [{"name": "主痰饮内搏", "desc": "滑脉主痰饮内蕴。原文“痰饮内搏，支塞肺络”“酿成痰浊”，症见咳嗽气喘、难于平卧、痰秽如脓，脉滑应痰浊壅盛，故主痰饮停聚、壅塞肺络之病机。"}, {"name": "主表寒里饮", "desc": "浮紧与滑并见，示外寒引动内饮，表寒里饮相合为患。原文“寒邪外束，痰饮内搏”并见寒热无汗与咳喘难卧，脉象揭示表闭与里饮同病，故主外寒引动内饮、表里同病之机。"}, {"name": "主痰热壅肺", "desc": "滑主痰，紧束之象兼胃有蕴热，痰浊与热郁结。原文“胃有蕴热，热郁而烦躁”“痰秽如脓”，舌苔薄腻而黄，脉浮紧滑示表寒里饮兼胃热，痰热壅肺成痈，故主痰热瘀结、壅塞肺叶之病机。"}], "n": {"主痰饮内搏": 1, "主表寒里饮": 1, "主痰热壅肺": 1}, "a": {"40": "主表寒里饮", "344": "主痰热壅肺", "21801": "主痰饮内搏"}, "t": 3, "np": 0}, "pc:左+浮+虚+缓": {"o": "左浮虚缓脉总主阳虚气弱，尤以脾阳不足为核心。浮为阳气浮越，虚为阳气不足，缓为鼓动无力，三者合见，提示阳气虚衰、机能减退。其具体病机可分三类：一为阳虚，因过汗亡阳，失于温煦；二为气虚，推动无力，形体失养；三为脾弱，运化失职，气机不畅。三者相互关联，阳虚为根本，气虚为表现，脾弱为关键环节，故临床可见足冷身寒、恶寒、易饥消瘦、梦遗、筋骨疼痛等症，虽似阴虚，实属阳虚气弱，治当温阳益气，不可滋阴降火。", "c": [{"name": "主阳虚", "desc": "左脉浮虚而缓，浮为阳气浮越于外，虚为阳气不足，缓为鼓动无力，总因伤寒过汗亡阳，阳虚不能温煦，故见足冷身寒、恶寒等症。原文断为阳虚，非阴虚火动。"}], "n": {"主阳虚": 2}, "a": {"3570": "主阳虚", "15220": "主阳虚"}, "t": 2, "np": 0}, "pc:右+大+浮+濡": {"o": "右·大浮濡脉总以浮大而濡为象，主暑湿、气虚与虚阳上浮三类病机。浮大主邪郁气逆或虚阳外浮，濡主湿伤与气弱。暑湿侵脾，气机内闭，则脉浮大而濡，伴身热淹久、体软色黄；暑湿伤气，中阳不运，则气虚不能鼓脉，脉亦浮大而软；肾水亏虚，虚阳上浮，尺部右浮大而濡，则见头风肢麻。三者相互关联：暑湿为外因，气虚为内因，虚阳上浮为虚损之变。总属本虚标实、气机失调之候，以益气疏化为治。", "c": [{"name": "主暑湿", "desc": "右脉浮大而濡，浮大主暑湿蒸郁、气不达邪，濡主湿伤脾气。原文见暑湿侵脾，中阳不运，体软色黄，身热淹久，汗出发疹，舌薄白而大，显系暑湿困阻中焦，气机内闭之象。"}], "n": {"主暑湿": 2}, "a": {"6940": "主暑湿", "7008": "主暑湿"}, "t": 2, "np": 0}, "c:弦+疾+坚": {"o": "弦疾坚脉总起来主气郁化火、痰热内结、邪势鸱张之实证。其形成多因平素饮食不节、气滞多痰，痰热内蕴，复感疟邪，或误投温补，致邪热深入，肝火亢盛，气机壅塞。脉象上，弦主气郁，疾主热盛，坚搏示邪结，三者相合，反映气郁、热盛、痰阻、邪结相互搏结的病理格局。各类病机之间关系密切：气郁为始动因素，气滞则痰凝，痰郁化热，热盛则脉疾；邪热与痰气搏结，深入肝经，则肝火亢盛，脉见坚搏。故弦疾坚脉虽以气郁、热盛、痰热、邪结、肝火分述，实则一体，总属邪实热盛、气机壅塞之候，提示病势鸱张，需清解透邪、化痰疏郁并进。", "c": [{"name": "主气郁", "desc": "弦脉为气机郁滞之象。原文两段均言'弦主气郁'，患者平素饮食不节、气滞多痰，脉见弦象，说明肝气不舒、气机壅塞是弦疾坚脉的基本病机之一。气郁日久可化火，与痰热相合，促使脉象由弦转疾、坚搏。"}], "n": {"主气郁": 2}, "a": {"13175": "主气郁", "13904": "主气郁"}, "t": 2, "np": 0}, "c:大+微+弱": {"o": "微弱大脉总主正气不足，尤以气分虚、气血两虚为要。脉微弱为“无阳”之征，反映气分不足，故太阳病见脉微弱者不可发汗；若脉大无力或微弱而渴，则属气血两虚，治宜补气血。两类病机均以虚为本：气分不足侧重卫外与托邪无力，气血两虚侧重营血亏耗与津液不布。二者可相互转化，气虚无以生血则气血俱虚，血虚气弱则脉更微弱。临证凭脉之微弱与大无力，辨虚之所在，分别以解肌和营或补益气血为治。", "c": [{"name": "主气分不足", "desc": "脉微弱为气分不足、无阳之征。原文言“脉微弱者，此无阳也”，并释“无阳从脉微弱看出，是言其气分不足也”。气分不足则脉道不充，故脉微弱；因正气不足，故不可发汗，宜桂枝二越婢一汤解肌。"}], "n": {"主气分不足": 2}, "a": {"20343": "主气分不足", "23978": "主气分不足"}, "t": 2, "np": 0}, "pc:右+弦+滑+小": {"o": "右弦滑小脉总起来主肝胃不和、中阳不足、痰湿内停之候。其脉象由弦、滑、小复合而成：左弦示肝木偏旺，右小滑示中阳不足、痰湿内停。三者相互关联：中阳不足则运化失职，痰湿内生，痰湿中阻又致肝木犯胃，形成肝胃不和、虚实夹杂之局。原文“中阳不足，肝木犯胃”点明病本在虚，病标在肝胃气逆与痰湿，故见晨起呕吐、得食尤甚、脘痛彻背。此脉所主病机以中虚痰滞、肝胃气逆为核心，虚、痰、气三者交织，病位在肝胃，切宜怡养。", "c": [{"name": "主肝胃不和", "desc": "脉左弦右小滑，左弦为肝木偏旺，右小滑为中虚痰滞。原文言“中阳不足，肝木犯胃”，肝气犯胃则晨起呕吐、得食尤甚，甚则脘痛彻背，故主肝胃不和、气逆犯胃之病机。"}], "n": {"主肝胃不和": 1}, "a": {"2830": "主肝胃不和"}, "t": 1, "np": 0}, "c:数+大+长": {"o": "长大数脉总起来主邪热亢盛之证。其脉长大数躁，长主气有余，大主邪盛，数主热，躁主热极，诸象相合，反映热邪炽盛，正气未衰，正邪交争剧烈。原文载服热药益甚而见此脉，断为阳明热炽，宜大剂白虎，有下证佐承气，可知此脉所主以实热为核心，尤以阳明经腑热盛为典型。两类病机中，主热盛为总纲，主阳明实热为具体病位，二者相互关联，实热亢盛是共同基础，临床须脉症合参以定治法。", "c": [{"name": "主热盛", "desc": "脉长大数躁，长主气有余，大主邪盛，数主热，躁主热极。原文服热药益甚，脉长大数躁，示阳明热炽，非轻剂可解，故主热盛。"}], "n": {"主热盛": 1}, "a": {"3535": "主热盛"}, "t": 1, "np": 0}, "pc:寸+数+大+空": {"o": "寸·数大空脉总属肺阴亏虚、虚热内扰之象。右寸候肺，脉数主热，空大主阴气不足、脉道不充，故其核心病机为肺阴亏虚，虚热内生。然原文又指出兼有阳明胃经湿热薰蒸之气，此湿热可上扰及肺，与虚热并存。故本脉所主以肺阴亏虚为本，虚热为标，并可兼见胃中湿热。三类病机中，肺阴亏虚是根本，虚热内扰由阴亏所致，胃中湿热则为兼夹之邪，临证需养阴为主，兼理湿热。", "c": [{"name": "主肺阴亏虚", "desc": "右寸候肺，脉数而空大，数为有热，空大为阴气不足、脉道不充。原文谓“肺虚则易招风”“阴气必虚”，是肺阴亏虚、虚热内扰，故脉数而空大。"}], "n": {"主肺阴亏虚": 1}, "a": {"5852": "主肺阴亏虚"}, "t": 1, "np": 0}, "pc:左+大+弱+缓": {"o": "左大弱缓脉总以气虚为本，兼见痰湿为标。弱缓大主气虚，右关滑主痰湿，二者相合，揭示脾虚气弱、运化失职、湿聚生痰之病机。痰湿中阻，中枢不运，则升降失司，胆木不降，肝阳上逆，变生耳聋等症。四类病机中，气虚为根本，痰湿为标象，脾虚生痰为中间环节，气痰阻络为最终病果，层层相因，总不离“气虚挟痰”四字。脉症相符，提示临证当以补气健脾、化痰通络为要。", "c": [{"name": "主气虚", "desc": "左脉弱缓大，弱为气衰，缓为气馁，大为气散，合而示气虚不运。原文谓“左弱缓大为气虚”，又言“气瘠于内，气弱则脾土少运”，故主气虚，尤以脾肺之气不足为要。"}], "n": {"主气虚": 1}, "a": {"7967": "主气虚"}, "t": 1, "np": 0}, "pc:关+细+沉+紧": {"o": "关·细沉紧脉总属厥阴肝经虚寒凝滞、相火不藏之候。左关候肝，沉为病在里，细为阴血不足，紧为寒邪内束，三象合见，揭示下焦虚寒、肝经凝滞为本，虚阳上浮为标。其主病机可归为三类：一为寒凝，紧脉主寒邪收引，症见足冷如冰；二为虚寒，沉细示阴血不足、下焦虚寒，与紧脉并见，故桂附不效；三为相火不藏，因寒凝肝经，相火失于潜藏，虚阳上浮，症见目赤、梦泄、夜寐不安。三者相互关联：虚寒为本，寒凝为标，相火不藏为变，形成本虚标实、寒热错杂之局。治当温养厥阴、固涩下元，而非单纯温补或清热。", "c": [{"name": "主寒凝", "desc": "脉紧为寒邪内束，沉为病在里，左关候肝，故关脉沉紧主肝经寒凝。原文症见足冷如冰，乃下焦虚寒、寒邪凝滞厥阴之象，紧脉正是寒邪内盛、气血收引之征。"}], "n": {"主寒凝": 1}, "a": {"10439": "主寒凝"}, "t": 1, "np": 0}, "pc:关+弦+滑+紧": {"o": "右关弦滑紧脉总起来主胸阳不振、阴邪痹阻之胸痹病机。弦紧反映阳气不舒、阴寒内结，滑则主痰湿阴邪。三者相合，提示阴寒痰湿之邪痹阻胸膈，胸阳不得宣通，故见胸中常闷、饮食少进。其病机核心为“阳郁”与“阴结”，而“痰湿”为阴邪之具体形态，三者相互关联：阴寒痰湿结聚，导致阳气不舒；阳气不伸，又使阴邪更易凝滞。治疗以通阳散结、化痰为法，方用瓜蒌薤白白酒汤加半夏，正是针对阳郁、阴结、痰湿三个环节。此脉虽仅见于右关，但关候胸膈脾胃，故其病机聚焦于胸膈阳气与阴邪之争，属本虚标实、阳微阴弦之候。", "c": [{"name": "主阳郁", "desc": "右关弦紧，关候胸膈，弦紧为阳气不舒之象。原文谓“胸中阳气不舒”，胸阳被阴邪所遏，不得宣通，故脉见弦紧。此乃胸痹病机之关键，阳郁不伸则胸闷、饮食少进。"}], "n": {"主阳郁": 1}, "a": {"10441": "主阳郁"}, "t": 1, "np": 0}, "c:弦+沉+伏": {"o": "沉弦伏脉总起来主邪郁于里、气机闭阻之病机，具体可因热郁、痰浊、寒凝或阳衰阴盛而见。沉为在里，弦为气机紧张或阴凝，伏为气闭不出。若沉弦而缓，多属痰热内伏、肝热遏伏，缓非脾弱而是痰浊阻气；若沉伏弦紧，则多属血气内虚、外寒闭阻、寒凝收引，见于痉病；若沉细弦伏并见，则为阳气衰微、浊阴内盛、络脉闭阻。各类之间以“邪闭于里”为共同基础，热郁与痰浊常相兼为患，寒凝与阳衰阴盛则多因虚致实，总以气机不得宣通为关键。", "c": [{"name": "主热郁", "desc": "沉弦为热邪郁遏于里，不得外达。原文脉沉弦而缓，沉弦示肝热遏伏，温散即显咽痛，为内风已动，热郁于内之征。"}], "n": {"主热郁": 1}, "a": {"14191": "主热郁"}, "t": 1, "np": 0}, "c:浮+小+濡": {"o": "浮小濡脉总属虚证，核心病机为阳气虚馁、中气亏虚。浮为气虚外浮，小濡为脉道不充、气血不足，按之不足尤显中气亏虚。原文载患者形瘦色白而脆，得遍身虫行奇疾，乃汗多亡阳、气虚不能温煦肌肤之象，非实邪为患。其下属浮小濡数脉主气阴两伤、虚热内扰；浮小濡缓脉主脾虚气弱、劳倦伤中；浮濡细小脉主外风引动内湿食滞、气血不充。诸类虽兼夹不同，然总以虚为本，或兼虚热，或兼劳倦，或兼外邪湿滞，皆不离气虚阳弱、中气不足之根本。故浮小濡脉总以虚证为纲，虚中或兼他邪，然其本在虚。", "c": [{"name": "主气虚", "desc": "脉浮小而濡，按之不足，为阳气虚馁之象。浮为气虚外浮，小濡为脉道不充，按之不足尤显中气亏虚。原文形瘦色白而脆，身如虫行，乃汗多亡阳、气虚不能温煦肌肤，故主气虚。"}], "n": {"主气虚": 1}, "a": {"15271": "主气虚"}, "t": 1, "np": 0}, "c:洪+散+乱": {"o": "洪散乱脉总属虚寒阳浮之危候。其脉洪大无伦，重取即散，洪大非实热，乃阴寒内盛、虚阳外越所致；散为里气虚寒，阳气无根。三者相互关联：虚寒为本，阳浮为标，霍乱为诱因与表现。此脉主寒霍乱吐泻大汗后，里气暴虚，阴寒内盛，逼阳外浮，故见脉洪散、面赤戴阳、腹胀如石等症。切不可误作实热而投破气劫药，当温里回阳为治。", "c": [{"name": "主虚寒", "desc": "脉洪大无伦而重取即散，洪大为真阳外越，散为里气虚寒。暴寒伤中，吐泻大汗，里气虚弱，阴寒内盛，故脉虽洪大却散乱无根，主虚寒之证。"}], "n": {"主虚寒": 1}, "a": {"16166": "主虚寒"}, "t": 1, "np": 0}, "pc:右+弦+沉+迟": {"o": "右·弦沉迟脉总起来主内寒肝郁、气血不足，并可兼见表邪未解。沉迟为寒，弦主肝郁，故内寒肝郁是其核心病机；沉而无力则主气血亏虚，左右脉俱沉无力尤显气血不足；若兼浮象，则提示外感表邪未解。三类病机可单独出现，亦可相兼为病，如内寒肝郁兼气血不足，或外感引发里虚寒郁。临床需结合左右脉力及兼脉，随证择药，如实热用茵陈栀子，食积用鸡内金山楂，便结用大黄麻仁等，体现辨证论治之灵活。", "c": [{"name": "主内寒肝郁", "desc": "脉沉迟而弦，沉迟为寒，弦为肝郁。原文明言“脉沉迟而弦主内寒肝郁”，寒性收引，肝气郁滞，故脉道沉迟而兼弦象，主里寒与肝郁气滞相兼之病机。"}], "n": {"主内寒肝郁": 1}, "a": {"20238": "主内寒肝郁"}, "t": 1, "np": 0}, "c:数+大+迟": {"o": "迟数大脉总起来主寒热虚实及气机升降失常。数脉主热，迟脉主寒，此为常理；然迟脉亦可因大气下陷而现，非独寒也。大脉主邪盛或虚阳外浮，与迟数合参，可辨寒热错杂、虚实夹杂之证。诸脉所主，以寒热为纲，兼顾气陷、虚损等病机。各类之间相互关联：热盛则数，寒盛则迟，气陷则迟而弱，虚阳外浮则大而数。临证需四诊合参，不可执一脉断病。", "c": [{"name": "主热", "desc": "脉数通常主热，因热力过盛则脉数。原文虽言大气下陷脉迟，但承认伏气化热存在，故数脉可反映热盛之病机。"}], "n": {"主热": 1}, "a": {"20430": "主热"}, "t": 1, "np": 0}, "pc:关+数+大+迟": {"o": "此关部数大迟脉，总起来主大气下陷兼伏热之证。其核心病机为胸中宗气亏虚下陷，导致心机跳动受病，脉来迟慢；虽兼伏气化热，但因大气陷而热力不能正常鼓动血脉，故脉不现数大而反迟。两类病机相互关联：大气下陷为本，热力失常为标，迟脉非单纯热力微弱所致，而是宗气陷与伏热并见之特殊表现。", "c": [{"name": "主大气下陷", "desc": "原文指出大气（宗气）贯心脉而行呼吸，若大气下陷则心机跳动受病，虽兼伏热而脉仍迟。脉迟非独热力微弱所致，实因宗气陷而斡旋无力，故脉来迟慢。"}], "n": {"主大气下陷": 1}, "a": {"20430": "主大气下陷"}, "t": 1, "np": 0}, "c:虚+弱+缓": {"o": "缓弱虚脉总属正虚之象，主气血亏虚、骨髓枯竭，并提示正虚邪陷之危候。所举段落中，妇人温病瘥后血脉未和，复因交接受邪成阴易病，脉见缓弱，说明气血已伤、骨髓失充，正气无力抗邪，故见身体重、气力转少、著床不能动摇等症。三类病机相互关联：气血虚为根本，骨髓竭为深重表现，正虚邪陷为转归，共同反映虚损基础上兼夹邪毒的病理状态。", "c": [{"name": "主血气虚", "desc": "脉缓弱为气血不足之象。原文谓“脉缓弱主血气虚”，妇人温病瘥后血脉未和，复因交接受邪，正气更伤，气血亏虚，故脉来缓弱无力。"}], "n": {"主血气虚": 1}, "a": {"21407": "主血气虚"}, "t": 1, "np": 0}, "c:细+沉+软": {"o": "沉细软脉总属正虚之象，以阴血亏虚、正气不足为基本病机。沉细主里、主阴血不足，软主正气无力，故凡见此脉，多提示气血阴津亏耗。在此基础上，可因虚致实、虚实夹杂，衍生出多种病机：阴虚不能制阳则虚热内扰，脉见躁疾或细数；阴不敛阳则虚阳外浮，脉浮大而空；脾阳不振则痰饮内停，脉沉细濡软；脾肾阳虚则水湿泛滥，脉沉细软小；正虚邪恋则疟邪湿滞，脉沉涩细软。各类病机之间以正虚为本，或兼虚热、或兼虚寒、或兼湿滞、或兼邪恋，总不离本虚标实、虚实夹杂之局。", "c": [{"name": "主阴血亏虚", "desc": "沉细为阴血不足、脉道不充之象，软为正气亏乏。原文'沉细而软'与内伤烦渴并见，说明阴津亏耗、气阴两虚，虚火上炎而致烦渴。"}], "n": {"主阴血亏虚": 1}, "a": {"25050": "主阴血亏虚"}, "t": 1, "np": 0}, "c:滑+紧+实": {"o": "滑实紧脉总起来主邪实内盛，以里热燥结为核心。滑主痰热内壅，实主邪气壅盛，紧主痛主实，三象相合，反映热邪与燥屎搏结于阳明之腑，气机壅滞，不通则痛。其具体病机包括里热炽盛、燥实内结、疼痛以及邪实正损。里热炽盛是基础，燥实内结是病位所在，疼痛为燥实阻滞气机之必然表现，而邪实正损则见于误治后真阴受损而邪热未去之变证。四类病机相互关联，总以邪实为纲，热、结、痛、损为目，临证当以攻下实热为主，兼顾护阴。", "c": [{"name": "主里热炽盛", "desc": "脉滑数而实，为里热炽盛之象。原文见发热蒸蒸、不恶寒、谵语、烦渴、小便赤等，皆阳明里热亢盛之征。滑主痰热内壅，数主热盛，实主邪气壅盛，故脉滑数而实直接反映热邪充斥内外。"}], "n": {"主里热炽盛": 1}, "a": {"25510": "主里热炽盛"}, "t": 1, "np": 0}, "c:弦+大+革": {"o": "弦大革脉总属虚证，以正气虚衰、脉失柔和为根本。其具体所主，一为虚劳亡血，二为妇人半产漏下，三为正气虚而脉失柔和。三者相互关联：虚劳亡血与半产漏下皆属精血亏耗，精血既亏，则脉道不充、气浮于外，故见弦大而革、失于柔和之象。弦大为虚阳外浮之征，革为中空之候，合而示正虚为本、脉失柔和为标。虽原文以药物考订为主，脉象仅作引证，然所引革脉主病，可归纳为虚劳、亡血、半产漏下及正虚脉失柔和数端，总不离一个「虚」字。", "c": [{"name": "主虚劳亡血", "desc": "原文引「脉革」「脉弦而大之革」，并明言革脉主虚劳亡血。弦大而革，脉失柔和，反映精血亏虚、脉道不充，故主虚劳、失血之证。"}], "n": {"主虚劳亡血": 1}, "a": {"25873": "主虚劳亡血"}, "t": 1, "np": 0}, "pc:左+沉+紧": {"o": "左沉紧脉总属里寒实证，以寒邪内凝、气血滞涩为核心病机。沉主里，紧主寒主痛，左脉候血候肝，故其病位多在厥阴肝经及下焦血分。所主病机包括寒凝、里实、水停、虚寒及寒热错杂五类：寒凝为基本病机，寒邪内束，气血不通；里实强调寒邪内伏，疼痛由生；水停则因寒水不化，泛溢为肿；虚寒见于阳气不足，寒从中生；寒热错杂则由寒郁化热或误治致变。五类相互关联，均以寒邪为枢，或兼水饮，或兼正虚，或兼热郁，反映了沉紧脉在左脉所候的肝血分病变中的复杂表现。", "c": [{"name": "主寒凝", "desc": "紧脉主寒，沉紧提示寒邪内侵，气血凝滞。如原文“沉为在里，紧为寒为痛”，左脉候血候肝，寒邪深入厥阴，阳郁不达；又“寒湿内伏，脉乃沉紧”，说明寒湿内停亦见沉紧。"}, {"name": "主水停", "desc": "沉脉主水，紧脉主寒，沉紧并见可主寒水内停。原文“左脉沉紧，紧则为寒，沉则为水”，指出肝肾虚肿时寒水内停之机，水寒不化，泛溢肌肤。"}, {"name": "主寒热错杂", "desc": "沉紧脉可兼数象，形成寒热错杂之候。如左数沉紧脉，左脉沉细欲无主清阳下陷，右脉沉紧而数主瘀血受寒、热郁于内，虚、瘀、寒、热交织，故见寒热错杂。"}], "n": {"主寒凝": 2, "主水停": 1, "主寒热错杂": 2}, "a": {"5587": "主寒凝", "19485": "主寒热错杂", "21801": "主寒热错杂", "24869": "主水停", "25001": "主寒凝"}, "t": 5, "np": 0}, "pc:左+沉+伏": {"o": "左沉伏脉总起来主气机郁闭、痰浊格拒、表邪内遏及瘀血内停。其基本病机为邪阻气机，脉道不畅，故脉沉伏不起。各段中，沉伏脉多与滑大、弦滑等脉并见，提示痰、气、表邪等实邪为患。如左沉伏而右滑大，为痰格中焦、气闭下焦；初按沉伏为表邪郁闭；则从反面指出真瘀血当见沉伏。可见沉伏脉所主非一，须结合兼脉及症候辨别：气闭者多兼滑大，表邪者多兼浮紧，瘀血者多兼芤涩。总之，沉伏脉以邪实气闭为核心，虚证少见。", "c": [{"name": "主气闭", "desc": "沉伏脉主气机郁闭。原文如左脉沉伏，断为“气闭下焦”，症见二便不通、呕吐；亦云“沉伏为气闭于内”。因气机郁滞，脉道不畅，故脉沉伏不起，多见于下焦气闭、二便不通之证。"}, {"name": "主痰格", "desc": "沉伏脉可因痰浊壅盛、格拒中焦而致。如左脉沉伏，右脉滑大，断为“痰格中焦，气闭下焦”，痰阻气机，脉气不得宣通，故沉伏。此痰格与气闭常相兼为病。"}, {"name": "主表邪", "desc": "沉伏脉亦主表邪郁闭。如“初按脉沉伏，有表邪者，续命汤散邪”，因外邪束表，阳气被遏，脉气不能外达，故脉沉伏，治当散邪。此与气闭、痰格之沉伏不同，属表证之沉伏。"}], "n": {"主气闭": 2, "主痰格": 2, "主表邪": 1}, "a": {"5979": "主痰格", "6104": "主气闭", "6273": "主痰格", "6398": "主气闭", "24619": "主表邪"}, "t": 5, "np": 0}, "pc:左+弦+洪": {"o": "左弦洪脉总属肝木化火、热盛阴伤之候。弦为肝脉，洪为火热，故核心病机为肝火亢盛；火盛灼阴，则兼阴伤；木火刑金，灼津为痰，则痰热内蕴；火盛阳升，肝阳上僭，则气冲、面赤、不眠；若邪热内陷，郁结不达，则脉见洪数中带紧涩。诸类以肝火亢盛为始，进而导致阴虚阳浮、气逆血涌、肾火不足等变证。各段原文所示，或为肝阳上亢、火势极盛，或为无根之火浮于外，或为气逆血上冲犯阳明，或为肾不足而火妄动，皆围绕火盛与阴伤两端展开，故总以肝火亢盛为主，兼见阴虚、气逆、肾火等兼夹病机。", "c": [{"name": "主肝火亢盛", "desc": "弦为肝脉，洪为火热，左脉弦洪并见，是肝木化火、火势亢盛之象。原文见脑疽坚肿、脓水不畅、烦躁不安，皆火盛之征；脉弦洪不减，示火势未衰，故主肝火亢盛。"}, {"name": "主阴虚阳浮", "desc": "劳瘵之证属足三阴亏损，虚热无火，脉弦洪为无根之火浮于外，左尺虚弱或细数，示肾阴亏而虚火妄动。火土太旺，金水衰涸，血随火泛而衄吐血，故主阴虚阳浮、元气不摄。"}, {"name": "主气逆血涌", "desc": "右脉弦而洪，左脉弦大而芤，弦为肝逆，洪大为气火亢盛，芤则阴血内亏、血不归络。水不养肝，肝不藏血，气逆血上冲犯阳明，致有狂吐，脉不安静如波涛不定，故主气逆血涌。"}, {"name": "主肾火不足", "desc": "左尺脉浮洪，肾属水冬脉当沉，浮洪为肾不足、肾家有火。症见小便疾速不能忍且有余沥，大便燥结，语言謇涩，多痰声重，故主肾水不足、虚火妄动。"}], "n": {"主肝火亢盛": 2, "主阴虚阳浮": 1, "主气逆血涌": 1, "主肾火不足": 1}, "a": {"12715": "主气逆血涌", "14885": "主肝火亢盛", "14886": "主肝火亢盛", "23196": "主阴虚阳浮", "27681": "主肾火不足"}, "t": 5, "np": 0}, "pc:左+大+濡": {"o": "左·大濡脉总起来主肝风内动、中阳虚弱、湿阻气滞及肝脾不调之病机。左脉大主厥阴内风掀越，肝风震动；右脉濡主阳明中虚，气血不充，或脾运不健，湿邪内蕴。若左大右濡并见，多为肝风内动与阳明中虚并存，如老年暴中、舌强肢软；若濡而左较大，则侧重肝旺脾弱、湿阻气滞，见脘胀面浮。诸类之间，肝风与中虚常相互影响，湿阻与肝脾不调亦密切相关，总属本虚标实、气血失调之候。", "c": [{"name": "主肝风内动", "desc": "左脉大主肝风震动，如原文'左大主厥阴内风掀越'、'左大乃肝风震动之象'，并见舌强肢软、神惫欲寐等症，为肝风内动、气血上逆之候。"}, {"name": "主肝脾不调", "desc": "左脉较大为肝气偏旺，右濡为脾湿不运，原文'脉濡左较大'，症见脘胀、面浮，乃肝旺脾弱、气机失调之病机。"}], "n": {"主肝风内动": 2, "主肝脾不调": 1}, "a": {"777": "主肝风内动", "5008": "主肝风内动", "9821": "主肝脾不调"}, "t": 3, "np": 0}, "pc:尺+弦+细": {"o": "尺·弦细脉总起来主肾虚肝郁、精血亏虚、肝风内动及阳衰寒凝之病机。其核心在于肾精亏于下、肝木失于濡养，形成下虚上实或本虚标实之候。脉细主精血不足，尺部细尤显肾精亏虚；弦主肝郁气滞、风动或疼痛。三类病机相互关联：肾虚肝郁者，精血亏虚而肝气偏旺；肝虚风动者，水不涵木而内风妄动；阳衰寒凝者，下焦阳虚而寒浊凝聚。总属本虚标实，以肾虚精亏为本，肝郁、风动、寒凝为标，虚实夹杂。", "c": [{"name": "主肾虚肝郁", "desc": "尺细为肾精亏虚，关弦为肝木偏旺，肾虚则二阴失养，肝郁则气机不畅。原文言“脉来尺细关弦，肾家之虚也”，并见腰痛苦痛、二便不利，故主肾虚肝郁、精血不足之病机。"}, {"name": "主肝虚风动", "desc": "弦细为肝血不足、木失濡养之象，尺脉细主肾水虚。原文谓“坎水滋木，虚则木失养而风火妄动”，水不涵木则内风妄动，外风引之而头风时发，肢节酸麻，故主肝虚风动、精血亏虚之病机。"}, {"name": "主阳衰寒凝", "desc": "弦主气滞、主痛，尺细主下焦肝肾不足。原文述“阳衰则寒浊凝聚少腹”，入暮膨满，腑气不爽，病在下焦肝肾，故脉弦尺细，主阳衰寒浊凝聚下焦、气机不畅之病机。"}], "n": {"主肾虚肝郁": 1, "主肝虚风动": 1, "主阳衰寒凝": 1}, "a": {"4693": "主肾虚肝郁", "7008": "主肝虚风动", "11605": "主阳衰寒凝"}, "t": 3, "np": 0}, "c:沉+虚": {"o": "沉虚脉总属里虚之候，以正气不足为核心病机。沉主病位在里，虚主正气亏虚，故凡脏腑气血阴阳不足、脉道不充者，皆可见沉虚之脉。其具体所主，可因虚损性质与病位不同而分为数类：一为里虚，乃基本病机，涵盖气血阴阳俱亏；二为气陷，因中气不足、升提无力而见脱肛等症；三为胃逆，因脾胃俱虚、气机逆乱而致哕；四为虚劳，乃虚损日久、气血耗伤之候；五为邪陷，因正虚无力托邪，邪气内陷。各类之间相互关联：里虚为共同基础，气陷、胃逆、虚劳、邪陷皆在里虚基础上衍生，或为虚之甚，或为虚而兼滞，或为虚而受邪。沉虚脉总以虚为本，然虚中可兼气机失调、邪气内陷等复杂病机，临证当结合部位与兼脉细辨。", "c": [{"name": "主里虚", "desc": "沉主病位在里，虚主正气不足，故沉虚脉总属里虚之候。原文如脉沉虚，年逾六旬，沉主里，虚主不足，为气虚下陷、阴血亏虚之象；右手关上脉沉而虚，关候脾胃，沉虚主脾胃俱虚。可见沉虚脉反映脏腑气血阴阳亏虚于内。"}, {"name": "主气陷", "desc": "沉虚脉可主中气不足、升提无力，气机下陷。如脱肛肿痛，脉沉虚，知为气虚下陷，内服滋阴清提补药而顿缩。沉虚示中气亏虚，无力升举，故见脱肛等气陷之症。"}, {"name": "主胃逆", "desc": "沉虚脉见于关部，可主脾胃俱虚、胃气上逆。如右手关上脉沉而虚者，病善哕也，因脾胃俱虚，受风邪，新谷不能传化，谷气与胃气相干，胃逆脾胀，气逆遇冷则哕。沉虚反映脾胃虚而气逆。"}], "n": {"主里虚": 1, "主气陷": 1, "主胃逆": 1}, "a": {"16410": "主气陷", "21809": "主里虚", "21998": "主胃逆"}, "t": 3, "np": 0}, "pc:尺+弦+微": {"o": "尺部弦微脉总起来主正虚邪伏、阳气衰微之病机。微脉主营气不足、阳气衰微，弦脉主邪郁、肝郁或寒饮内停。二者相合，多见于虚寒泄泻、虚疟等证，其核心为正气亏虚而邪气内陷。从所举两案看，一为年高久泻，脾肾阳弱，肝经虚寒，水湿不化；一为少阳疟邪内陷，胃气大虚，伏邪未透。虽病种不同，但均以正虚为本，邪伏为标。微弦脉所反映的正是虚中夹实、正虚邪恋的病理状态。各类之间相互关联：虚寒可致阳衰，阳衰则邪易内陷；疟邪内陷又进一步耗伤胃气，形成恶性循环。故临证见尺脉弦微，当以扶正为主，兼以透邪，不可妄攻。", "c": [{"name": "主虚寒", "desc": "尺脉弦微，微为阳衰，弦为肝郁，合之则肝经虚寒、脾肾阳弱。原文见年高久泻，肠鸣漉漉，溏泄如冷水，脉沉弦缓小，正合虚寒泄泻之机。故弦微脉主阳气虚衰、寒湿内盛之证。"}], "n": {"主虚寒": 2}, "a": {"2900": "主虚寒", "6686": "主虚寒"}, "t": 2, "np": 0}, "pc:左+缓+急": {"o": "左·缓急脉总以湿热郁蒸、气机升降失司为核心病机。右缓主湿郁气分，左急主肝风内动，二者并见，反映湿热酒腥相并，阻挠清气游行，营卫循环不利，清浊升降悖逆。其症候群如头如裹、昏寐、瘛痉、咳痰映红、便溏带血等，皆由此派生。各病机类别相互关联：湿热郁蒸为根源，气分湿郁与肝风内动为左右脉象分属，升降失司为整体气机后果，邪著气分延血为病势发展趋势。脉象缓急并见，提示病位在气分而涉肝风，病性属湿热郁蒸、本虚标实，久延可入血分。", "c": [{"name": "主湿热郁蒸", "desc": "原文明言‘水谷酒腥湿热相并郁蒸’，脉右缓左急，右缓为湿郁气分，湿热阻挠清气游行，故见头如裹、昏寐、不饥不渴、舌白糜腐等症，脉象反映湿热内蕴、气机壅滞之病机。"}], "n": {"主湿热郁蒸": 2}, "a": {"4559": "主湿热郁蒸", "4916": "主湿热郁蒸"}, "t": 2, "np": 0}, "c:动+促": {"o": "促动脉总起来主病机为邪实阻滞与热邪内陷两类。其脉象特征为脉动加速中偶现龃龉，往来涩滞不畅，非如结代之歇止。一类因痰血郁于隧道，气血运行受阻，脉见促动而浊，主积痰肝风、痰瘀阻络，甚则痱中之机；另一类因外感之热内陷，促其跳动加速，脉见促急，主热邪内陷、表里俱热。二者虽同见促动之象，但一为痰瘀有形之阻，一为热邪无形之促，病机虚实不同，临证当结合兼症辨析。", "c": [{"name": "主痰瘀阻络", "desc": "促动脉往来如有阻滞，如案4所述‘脉浊右手如促如动，往来之间，如有阻滞’，因痰血郁于隧道，气血不畅，故脉见促动而涩滞，主积痰肝风、痰血阻络之病机。"}], "n": {"主痰瘀阻络": 2}, "a": {"11218": "主痰瘀阻络", "20031": "主痰瘀阻络"}, "t": 2, "np": 0}, "pc:右+虚+濡": {"o": "右·虚濡脉总起来主气阴两虚、湿邪内蕴之病机。虚脉主正气不足，或为暑热耗气，或为纵欲伤阴损阳；濡脉主湿邪黏滞，或为暑湿郁肺，或为阴阳两虚之濡软。两类病机虽一为外感暑湿伤气，一为内伤阴阳两虚，但均以虚为本、以濡为标，虚示正气亏耗，濡示湿滞或阴血不充。右部候气，右脉虚濡尤重肺脾气分，故外感见暑湿郁肺，内伤见气阴两虚。二者可相互转化：暑湿久羁耗气伤阴，可致虚濡更甚；阴阳两虚之体易感暑湿，又添新邪。临证当辨外感内伤，虚濡并见者，总以扶正化湿为要。", "c": [{"name": "主阴阳两虚", "desc": "右脉软小乏力、左脉濡虚，为阴阳两虚之象。软小乏力示阳气不足，濡虚示阴血亏虚，右脉候气、左脉候血，两脉并见则阴阳俱损。原文以纵欲致虚为背景，强调阳密乃固，阴阳不和则病，故虚濡脉主阴阳两虚。"}], "n": {"主阴阳两虚": 2}, "a": {"15482": "主阴阳两虚", "16748": "主阴阳两虚"}, "t": 2, "np": 0}, "pc:六+虚+小": {"o": "虚小脉总主气血两虚、阴阳俱损。其脉形虚小乏力，为脉道不充、正气亏虚之象。两段原文均见六脉虚小乏力：一因大病久耗，气血未复；一因经水淋漓，去血过多，阴亏阳弱。虚小脉所主病机以气血两虚为基础，可兼失血阴亏与阳气衰弱。三者相互关联：气血久亏则阴血不足，阴损及阳则阳气亦弱；失血过多则阴亏阳弱，气血两伤。故虚小脉总属正虚，治宜益气扶阳、固气统血，不可纯用阴柔之品。", "c": [{"name": "主气血两虚", "desc": "虚小脉为气血久亏之象。原文两段均见六脉虚小乏力，一因大病两三月气血未充、肌瘦神疲，一因经水淋漓月余去血过多，皆示气血两亏，脉道不充，故脉形虚小乏力。"}], "n": {"主气血两虚": 2}, "a": {"15598": "主气血两虚", "15847": "主气血两虚"}, "t": 2, "np": 0}, "pc:双+滑+沉": {"o": "双·滑沉脉所主病机以水饮内停为核心，兼及寒、虚及饮聚偏处。沉滑直接主饮，因水饮内结、痰湿流动而脉沉滑；双弦主寒，因寒邪收引、阳虚寒生；脉微、脉虚主阳气不足，因饮病日久或误下伤阳；偏弦主饮聚一处，因饮邪偏聚局部、气机拘急。诸类均围绕饮邪为患，或寒饮相兼，或虚实夹杂，或饮停部位不同而脉象各异。原文强调“水饮为病脉无定象”，当结合喘满、短气、悸、胁下痛等症，辨饮停浅深及兼夹寒虚，不可执一脉论治。", "c": [{"name": "主饮", "desc": "沉滑脉主水饮内停。原文言“脉沉滑者留饮病”“脉沉者有留饮”，沉为水饮内结、病位在里，滑为水饮流动、痰湿内盛。饮邪停聚心下、胁下或肠间，故脉见沉滑，并伴喘满、短气、悸、胁下痛等症。"}], "n": {"主饮": 2}, "a": {"21659": "主饮", "22018": "主饮"}, "t": 2, "np": 0}, "pc:两+数+虚": {"o": "两·数虚脉总属正气亏虚、津液耗伤而兼虚热之候。其脉虚细小数，小弱无力，非实热实邪。原文因湿温误用攻下，克削过甚，致津液元气俱伤，故脉见虚数。虚为本，津伤为虚之具体，虚热为虚所生之变，三者相因：元气亏虚则脉小弱，津液耗伤则舌燥无津、手指蠕动，阴不制阳则虚数。故其主病以虚损为核心，津伤与虚热皆由虚所致，总为不足之象，忌用克伐。", "c": [{"name": "主虚", "desc": "脉虚数而小弱，虚细无力，为正气亏虚之象。原文谓‘克削过甚，津液元气俱伤’，见面色黯淡、舌燥无津、手指蠕动、心悸不寐，皆由误下克削，元气阴液耗损，脉道不充，故主虚。"}], "n": {"主虚": 1}, "a": {"758": "主虚"}, "t": 1, "np": 0}, "pc:右+涩+坚": {"o": "右涩坚脉总起来主脾虚血少、中焦气滞及劳伤中气虚。右涩为脾虚血少、中焦气滞，坚为气机壅滞，合之则中焦气困。原文虽言阴虚起见，但脉左坚右涩，右涩坚突出中焦为急，症见冲年形瘦、腹胀食减便溏、失血后日加孱弱，故断为劳伤中气虚。三类病机相互关联：脾虚血少与中焦气滞并存，久则劳伤中气虚，总以中焦脾胃困惫为核心，阴虚为兼，中气先困为急。", "c": [{"name": "主脾虚血少", "desc": "右涩坚脉中涩象主脾虚血少。原文右涩为脾虚血少、中焦气滞，症见腹胀食减便溏、失血后日加孱弱，皆脾虚运化无力、血少不荣之征，故涩脉主脾虚血少。"}], "n": {"主脾虚血少": 1}, "a": {"983": "主脾虚血少"}, "t": 1, "np": 0}, "pc:两+涩+弱": {"o": "两脉涩弱，总属虚损之候，以肾虚为本，兼见气虚与血少滞涩。涩主血少滞涩，弱主气虚，二者合见，反映精血亏虚、阳气不足，脉道不充且鼓动无力。原文明确指出“此属肾虚，失于收纳，藏聚少司，病根在下”，故其核心病机为下元虚衰、肾失封藏。肾虚则精血不能充养筋骨，故见痿躄、左足偏枯、步履皆废；肾督空虚，故背脊喜捶。气虚与血少相互影响：气虚则推动无力，血行滞涩；血少则脉道不充，涩象更显。三者以肾虚为根，气虚、血少为标，共同构成虚损病机。", "c": [{"name": "主肾虚", "desc": "原文指出“此属肾虚。失于收纳。藏聚少司。病根在下”，两脉涩弱合见，为下元虚衰之征。肾主藏精、主骨，虚则收纳无权，精血不能充养筋骨，故见痿躄、偏枯、步履皆废，背脊喜捶亦肾督空虚之象。"}], "n": {"主肾虚": 1}, "a": {"2163": "主肾虚"}, "t": 1, "np": 0}, "pc:尺+弦+实": {"o": "尺·弦实脉总起来主下焦实滞、气机壅阻之证。弦为气滞、为痛、为风，实为邪壅，尺部应下焦，故其核心病机是湿热瘀血搏结于下焦魄门，气机不畅而痛。原文一例内痔结粪疼痛夜甚，左弦尺弦实、右浮弦，正示下焦湿热瘀结为本、气滞疼痛为标，兼有风热上扰之象。诸类关系为：气滞与邪壅是弦实并见的基础，气滞血壅则痛，湿热瘀结于下焦则尺实，风热上扰则见浮弦，五者由本及标、由内及外，共同构成'下焦实滞兼风热'的完整病机图景。", "c": [{"name": "主痛", "desc": "原文'弦主痛'，左弦、右浮弦并见，弦脉为气机紧张、经脉拘急之象，故主疼痛。内痔结粪疼痛不已、夜甚，正合弦脉主痛之机，痛由气滞血壅、魄门拘急而作。"}], "n": {"主痛": 1}, "a": {"3030": "主痛"}, "t": 1, "np": 0}, "c:洪+涩": {"o": "洪涩脉总起来主寒热错杂、气血壅滞、瘀热互结及虚实夹杂。洪脉主热盛气浮，涩脉主血行不畅、瘀滞，二者并见，多因热邪内蕴，灼血成瘀，或寒热相搏，气血不通。原文左寸忽洪忽涩、迟数无定，因冷酒寒热相搏致腿疼筋缩，示寒热错杂、气血壅滞；膈痛脉洪大而涩，先清热行血痛止，后因劳倦忍饥痛大发，知为虚，示瘀热互结兼虚实夹杂。各类之间，寒热错杂与气血壅滞常相因，瘀热互结可致实，久则伤正成虚实夹杂，总以热、瘀、寒、虚交织为病机特点。", "c": [{"name": "主寒热错杂", "desc": "脉洪涩并见，洪为热象，涩为寒湿凝滞，迟数无定更示寒热交替。原文左寸忽洪忽涩、迟数无定栖，因饮冷酒，酒性热而冷饮犯寒湿，寒热相搏，故脉象乍洪乍涩，主寒热错杂之病机。"}], "n": {"主寒热错杂": 1}, "a": {"4309": "主寒热错杂"}, "t": 1, "np": 0}, "pc:右+濡+空": {"o": "右濡空脉总属虚实夹杂、形神两伤之候。其核心病机为肝胃络伤，而络伤之因在于情怀不舒、气郁化火，兼之肝血不足与胃气虚弱。右濡主胃气虚弱，左空主肝血不足，二者并见，示气血耗损于内，络脉失养；气郁则气滞络损，血不循经，故见右胁痛、呛痰血块。形瘦食减为脾胃虚弱之征。四类病机中，络伤为标，气郁为诱因，胃虚与肝血虚为本，标本相兼，虚实互见。总以甘缓主治，缓肝急、养胃络，使气血渐复，络脉得养。", "c": [{"name": "主络伤", "desc": "右濡空脉主络脉损伤。原文见右胁先痛、呛痰血块，明言“肝胃络伤”。右濡为胃气虚弱，左空为肝血不足，肝胃络脉失养，加之郁气滞络，故络伤而痛、血溢脉外。脉之濡空反映络脉不充、血行失和。"}], "n": {"主络伤": 1}, "a": {"8520": "主络伤"}, "t": 1, "np": 0}, "c:弦+短": {"o": "弦短脉在本段所主，总以肝郁气滞、水湿不运为核心，进而累及血分与脾运。脉弦为肝木乘脾之象，肝失疏泄则气机壅滞，脾不运湿则水谷之湿内停，故见溺短、黄肿、脘腹膨胀；气滞日久则血稽留少腹成瘕、脘中聚痞，形成气、水、血交结之肿胀重症。四类病机相互关联：肝郁乘脾为始动环节，水湿内停为病理产物，气滞血瘀成瘕为病进之变，肿胀重症为最终转归。弦脉既主肝郁，又主饮、主痛、主积，故本脉所主实为气滞、水停、血瘀互结之复杂病机，提示邪实正虚、病情深重。", "c": [{"name": "主肝郁乘脾", "desc": "脉弦为肝木之象，案中产后失调、饮食失节致气机壅滞，肝失疏泄则乘脾，脾运失职，故脉弦而见脘腹膨胀、饮食日减、精神日疲，为肝郁脾困之征。"}], "n": {"主肝郁乘脾": 1}, "a": {"11024": "主肝郁乘脾"}, "t": 1, "np": 0}, "pc:两+弦+和": {"o": "两关弦劲不和脉总属肝胃同病，以肝气横逆为核心，兼见胃络受伤、气火上逆及肝营虚损。弦劲为肝气失和之象，关部候肝胃，故脉见两关弦劲不和，提示肝气横逆犯胃，胃络受损，气火上逆则咳呛胁痛，失血后肝营自虚，而脉仍弦劲，示肝阴不足、气火未平。四类病机相互关联：肝气横逆为始动因素，胃络受伤为传变结果，气火上逆为病理产物，肝营虚为失血后转归。总以肝胃不和、虚实夹杂为特点，治当和养肝阴、通络理气，气和则血降火平。", "c": [{"name": "主肝气横逆", "desc": "脉见两关弦劲不和，关候肝胃，弦劲为肝气横逆之象。原文谓‘弦劲为肝气横逆’，气逆则胁痛、咳呛，甚则气火上逆，失血。此脉象反映肝气失于柔和，横逆犯胃，为病机之核心。"}], "n": {"主肝气横逆": 1}, "a": {"11769": "主肝气横逆"}, "t": 1, "np": 0}, "pc:六+动+乱": {"o": "动乱脉总属实证，主风痰壅盛、气血逆乱。其脉来乱动如沸泉，非虚候可比。风痰内壅，气机闭阻，血随气逆，故脉道不宁；痰浊上扰，蒙蔽清窍，则昏乱颤汗、口噤腹满；气血逆乱，筋脉失约，则手足乍屈乍伸。此脉以邪实为主，治当祛风涤痰、降气下逆，邪去则脉自平。两类病机相互关联：风痰为病本，气血逆乱为病势，痰盛则气逆，气逆则脉乱，总以“风痰实证”统之，非虚损所致。", "c": [{"name": "主风痰", "desc": "原文载“六脉乱动，沸如泉涌”，并明言“此风痰也”。风痰壅盛，气血逆乱，脉道不宁，故脉来动乱如沸。伴昏乱颤汗、口噤腹满，皆风痰上扰、气机闭塞之象，下之则愈，证实为风痰实证。"}], "n": {"主风痰": 1}, "a": {"17250": "主风痰"}, "t": 1, "np": 0}, "pc:尺+弦+浮": {"o": "尺部弦浮脉在内伤自汗的语境中，主要提示两类病机：一是阳虚不固，自汗出而脉浮，属阳气虚浮；二是水亏火旺，左尺浮洪无力，为肾水不足、虚火上炎。二者皆以虚为本，浮脉为虚阳或虚火外浮之象，而非表邪。弦脉在此段未直接论及，然左关浮弦为挟风邪，可推知弦浮并见亦主风动或虚风内扰，但核心仍围绕阳虚与水亏火旺。总以正虚为本，浮脉为标，治当温阳固表或滋阴降火。", "c": [{"name": "主阳虚自汗", "desc": "原文开篇明言“若内伤自汗，属阳虚也”，并主以补中益气汤加熟附子等温阳固表之品。脉浮而自汗，为阳气虚浮不能固摄，故浮脉主阳虚不敛，自汗为其证。"}], "n": {"主阳虚自汗": 1}, "a": {"18419": "主阳虚自汗"}, "t": 1, "np": 0}, "pc:左+涩+迟": {"o": "左涩迟脉总属肝木为病，以肝气虚实、气机逆乱为核心。其脉见于左关，左关候肝，涩主血滞，迟主虚寒，合而观之，反映肝经气血运行不畅。原文以弦长为肝之平脉，实弦为太过病在外，虚微为不及病在内，沉急为肝气逆，诸脉皆从肝木太过不及立论。故涩迟脉所主病机可归为三类：肝实、肝虚、气逆。肝实者邪气壅盛，肝虚者气血不足，气逆者疏泄失常，三者皆以肝为中心，虚实之间可相互转化，气逆常因虚实失调而发。总以调和肝木、疏畅气血为要。", "c": [{"name": "主肝实", "desc": "原文以脉实而弦为太过，病在外，令人忘忽眩运；又肝实则两胁下引痛、喜怒。涩迟脉见于左关，左关候肝，脉实主邪气盛，迟涩为气血壅滞，故主肝实之证，气机不畅而见胁痛、情志异常。"}], "n": {"主肝实": 1}, "a": {"19357": "主肝实"}, "t": 1, "np": 0}, "c:长+硬": {"o": "长硬脉总起来主气机逆乱、火盛阴亏之证，以肝、胃、冲脉气火上逆为核心。其脉长主气逆有余，硬主劲急亢盛，故凡见长硬，多示脏腑气化有升无降，气血随之上冲。就所主病机而言，可分四端：一为肝火炽盛，火性上炎而脉道劲急；二为冲胃之气上逆，气逆不降而脉见长硬；三为血随气升，气火上冲则血亦上逆，甚则充塞脑部；四为阴亏火旺，失血日久真阴亏损，脉失濡养而弦硬兼数。四类之中，肝火与冲胃气逆为病之标、为气分之逆，血随气升为其演变之果，阴亏火旺则为本之虚，标本相兼，虚实错杂，故其治当泻肝降胃以折其逆，兼大滋真阴以顾其本。", "c": [{"name": "主肝火上逆", "desc": "原文左脉弦长，自释为肝火炽盛；右脉长而兼硬，因肝火挟冲胃之气上冲。长硬之象示气火有余、有升无降，故主肝经火盛、气逆上冲之病机。"}], "n": {"主肝火上逆": 1}, "a": {"20454": "主肝火上逆"}, "t": 1, "np": 0}, "pc:尺+沉+结": {"o": "尺·沉结脉总属里实气滞之候。沉为里脉，结为气机阻滞之象，二者相合，主邪结在里、气机不畅。原文明确指出'尺脉沉结，怒气所伤'，说明其核心病机为情志所伤、气结于内。此脉虽仅一段论述，但可归纳为两类：一主气滞，因结脉主气机阻滞，怒气伤肝则气结；二主里实，因沉脉主里，结脉主邪聚，提示病位在里而邪实内结。两类相互关联，气滞为因，里实为果，共同反映尺部沉结脉所主的里实气滞病机。", "c": [{"name": "主气滞", "desc": "沉主里，结主气机阻滞，故尺脉沉结主怒气所伤，气机郁滞于内。原文'尺脉沉结，怒气所伤'直接指明情志不遂、气结不行之病机。"}], "n": {"主气滞": 1}, "a": {"24687": "主气滞"}, "t": 1, "np": 0}, "s:虾游": {"o": "虾游脉总属无胃气之死脉，其象冉冉而起、寻复退没、不知所在，来去无根，忽有忽无，静中忽一跃。总起来主胃气败绝、真阴耗竭、阳气浮散、命门将绝及正气欲脱等危候。诸类之间相互关联：胃气败绝为根本，胃气一亡则真脏脉见；真阴耗竭与阳气浮散常并存，阴竭则阳无所附，阳浮则阴不能守；命门将绝乃肾中真气败露，为胃气败绝之深重阶段；正气欲脱则见于邪陷里虚之时，脉失根本而现虾游。各段原文均以虾游为危候，或断不可治，或虽勉与养阴而脉转应指方得生，可见其主病机总不离脏腑真气衰败、阴阳离决，预后多凶。", "c": [{"name": "主胃气败绝", "desc": "虾游脉冉冉而起、寻复退没、不知所在，来去无根，为无胃气之脉。原文称'此即无胃气之脉''真藏脉见'，脉失从容和缓之象，故主胃气已亡，脏气败绝，多属死候。"}, {"name": "主真阴耗竭", "desc": "虾游脉散乱忽有忽无，见于热证下痢脓血、舌黑而燥、夜多谵语，乃阳明热毒炽盛而阴液枯竭。原文谓'阴液枯竭、阳气浮散之危候'，脉失根本，故主真阴耗竭。"}, {"name": "主阳气浮散", "desc": "虾游脉静中忽一跃，冉冉而起、寻复退没，来去无定，为阳气欲脱而忽聚忽散之象。原文谓'阳气欲脱而忽聚忽散'，脉无根柢，故主阳气浮散，阴阳离决之危候。"}, {"name": "主命门将绝", "desc": "虾游与鱼翔并见，原文列为'命脉将绝'之真脏脉，谓'命脉将绝虾游鱼翔'。命门真气将绝，脉乍浮乍沉、去来无定，故主命门元气败绝，绝在膀胱，主死。"}, {"name": "主正气欲脱", "desc": "瘟疫经水适来，里虚邪陷，六脉微数极无伦次，又若虾游状。微为阳微，数为邪热，脉无伦次如虾游，是胃气衰败、正气欲脱之象，故主里虚邪陷、正气欲脱之危候。"}], "n": {"主胃气败绝": 7, "主真阴耗竭": 1, "主阳气浮散": 1, "主命门将绝": 2, "主正气欲脱": 1}, "a": {"3375": "主胃气败绝", "3376": "主胃气败绝", "3384": "主正气欲脱", "4166": "主真阴耗竭", "4167": "主胃气败绝", "17433": "主胃气败绝", "21184": "主阳气浮散", "21823": "主胃气败绝", "22821": "主胃气败绝", "22824": "主胃气败绝", "26549": "主命门将绝", "26659": "主命门将绝"}, "t": 12, "np": 0}, "pe:右+实": {"o": "右·实脉总起来主邪实壅盛于里，病位以阳明胃肠、中焦脾胃为核心，兼涉肺、肝、血络。实脉主邪结，右部候脾胃，故凡右脉实而有力，多提示有形实邪（燥屎、积滞、痰浊、湿热）与热邪相结，或气机壅滞不通。其具体病机可归为五类：里热实结、湿热壅滞、痰热结实、邪实正虚、三阳合病。各类之间以“邪实”为共同基础，或偏于热结，或偏于湿滞，或偏于痰凝，或兼正虚，或涉多经；然皆因邪气壅盛、正气未衰，正邪交争剧烈，故脉象实而有力。若实中兼虚，则又示邪实正伤、虚实夹杂之候。", "c": [{"name": "主里热实结", "desc": "右脉实而兼数、洪、大，主热邪与有形实邪结于阳明胃肠。原文见右部甚实、脉近六至、大便两三日一行，或右脉洪实为风温热入阳明之腑，皆因热盛与燥屎、积滞相结，腑气不通，故脉实有力。"}, {"name": "主湿热壅滞", "desc": "右脉实而兼缓、弦，主湿热积滞壅阻中焦或血络。原文谓右脉缓、左脉实，缓为湿滞，实为邪结，湿热混处血络之中；又右脉弦而有力、重按甚实，为湿热积滞交阻脾胃，气机不畅，故脉实。"}, {"name": "主邪实正虚", "desc": "右脉似有力而重按不实，或实中兼见虚象，主邪实未去而正气已伤。原文见下痢久气化已伤，外感之热侵入阳明，脉数六至而右脉重按不实，断为邪实正虚之候，因正虚不能鼓邪外出，故脉虽实而根不坚。"}, {"name": "主三阳合病", "desc": "右脉弦而有力、重按甚实，关前且浮，主三阳经气同病、邪盛于表里之间。弦主少阳，实主阳明，浮主太阳，右脉实尤显阳明邪盛，三阳合病则邪无出入之机，故脉象弦实而浮。"}], "n": {"主里热实结": 2, "主湿热壅滞": 2, "主邪实正虚": 2, "主三阳合病": 1}, "a": {"1556": "主湿热壅滞", "4484": "主湿热壅滞", "20080": "主三阳合病", "20315": "主里热实结", "20657": "主里热实结", "20661": "主邪实正虚", "23990": "主邪实正虚"}, "t": 7, "np": 0}, "pe:两+短": {"o": "两寸短脉总以气机不畅为核心，或为气郁，或为气虚，或为痰湿、火邪阻滞气机所致。短脉主气病，寸部候心肺，故病位多在上焦。气郁者，胸阳不展，见胸膈胀痛、梅核气；气虚者，心肺不足，见体倦汗多、惊悸梦遗；痰阻者，痰气交结，见喉中梗梗、鼻塞头晕；湿滞者，湿阻上焦，见身重胸满；火郁者，痰火壅阻，见胸痛痰血。诸类之间，气郁、气虚为本，痰、湿、火为标，常相兼为病。短脉虽主气病，然须合参兼脉：滑主痰，数主火，紧细主湿，弱主虚，故临证当辨虚实寒热。", "c": [{"name": "主气虚", "desc": "短脉亦主气虚，尤以心肺气虚为多。原文见两寸短弱无力，症见体倦气弱、汗多、心惊胆怯、梦遗等，因元气不足，无力推动血行，脉道不充，故脉短。左寸尤甚者，心气大弱，神不固精。"}, {"name": "主痰", "desc": "短脉可主痰浊内阻。原文见两寸短而关滑大搏指，症见喉中梗梗如炙脔、吞之不下吐之不出，此为痰气搏结，上焦气机不畅。痰阻清阳则鼻塞头晕，痰扰心神则心惊胆怯。短脉示气郁，滑脉主痰，合为痰气交阻。"}, {"name": "主湿", "desc": "短脉主湿浊壅滞，气机不畅。原文见湿温初起，两寸脉短不及本位，症见头痛、肢节疼、身体沉重、胸满不食，因湿阻上焦，阳气不布，脉道不利，故短。湿浊内蕴，气机郁滞，则脉短而紧细。"}, {"name": "主火", "desc": "短脉可主郁火内炽。原文见两寸短，关滑，两手皆数，症见胸膈胀痛、痰中紫色瘀血，因酒积郁火，痰热壅阻，灼伤血络。短主气郁，数主火，滑主痰，合为痰火郁结，气机不畅，火灼血络。"}], "n": {"主气虚": 2, "主痰": 2, "主湿": 1, "主火": 2}, "a": {"3912": "主湿", "6059": "主痰", "6085": "主气虚", "6238": "主火", "6353": "主痰", "6379": "主气虚", "6531": "主火"}, "t": 7, "np": 0}, "pe:关+微": {"o": "关·微脉总起来主虚，以气虚陷下、虚寒阳衰、气血两亏为核心，并可兼夹痰湿、郁热、气郁等标象。微为阳气衰微、鼓动无力，关候中焦脾胃，故关脉微多责之正气不足。其基本病机是气虚陷下，如右寸关微见如水上浮麻、左部不见，为大气下陷之危候；其次为虚寒阳衰，微缓、微弱多主下焦不固、奇经失摄；又主气血两亏，微细、微涩示脾肾气弱、肝血不足。在此基础上，虚处留邪，可兼夹痰湿中阻（滑微）、中焦郁热（数微）、气郁营亏（微紧）等，形成正虚邪恋、本虚标实之候。各类之间以正虚为根本，虚寒、气陷、血亏为不同侧重，兼夹邪实为虚中求实之变，总属虚多实少、以虚为主的脉象。", "c": [{"name": "主气虚陷下", "desc": "关脉微见，如水上浮麻，或右寸关微见而左部不见，为大气下陷、血脱气散之危候。微为阳气衰微，鼓动无力，故气虚陷下，清阳不升，可见气息奄奄、不省人事、欲大便等症。"}, {"name": "主虚寒阳衰", "desc": "关脉微弱、微缓，多主虚寒阳衰。微为阳气衰微，缓为胃气孱弱，故见下焦不固、奇经失摄，或吐泻交作、神烦口渴而舌白腹痛，乃阴寒未散、阳未全回之象。"}, {"name": "主虚中夹邪", "desc": "关脉微缓、微弱而兼弦数、洪长，或微涩而兼弦数，为正虚邪恋、本虚标实之候。微为正气不足，缓为胃气弱，虚处留邪，痰积湿热肝气可因元气不足而交阻，形成虚实夹杂。"}], "n": {"主气虚陷下": 2, "主虚寒阳衰": 1, "主虚中夹邪": 4}, "a": {"3915": "主虚中夹邪", "4307": "主虚中夹邪", "11587": "主虚寒阳衰", "19358": "主虚中夹邪", "19812": "主气虚陷下", "22934": "主虚中夹邪", "24710": "主气虚陷下"}, "t": 7, "np": 0}, "pe:左+结": {"o": "左结脉总主气机郁滞、脉道不利之病机，其具体可因气滞、热郁、痰瘀互结、火郁上壅等所致。各段原文显示，结脉非独主虚，亦常见于实热、气郁、痰瘀等证。如左脉弦右脉结为肝郁气滞；脉洪滑甚实而结为阳明实热兼肝气不舒；左脉结疟母为痰瘀互结；左寸搏指为火郁上壅。下属涩结脉主气血痹涩、阴液枯槁；弦结脉主肝郁气结与肾阳衰微；结促脉主热郁气滞、积热内伏。诸类之间，气滞与热郁常相因为病，痰瘀可致气机阻隔，火郁亦由气壅不降。总以气机不畅、脉道不利为共同环节，虚实寒热皆可致结，临证需结合兼脉及症候辨析。", "c": [{"name": "主气滞", "desc": "结脉主气机郁滞、脉道不利。原文如左脉弦右脉结，情怀抑郁，气勃于中，五志过极皆从火化，示肝郁气滞；又左脉结因肝气不舒，气机阻隔，虽脉洪滑甚实，结仍由气滞所致。气滞则脉行断续，故见结象。"}, {"name": "主热郁", "desc": "结脉主热邪壅滞、气机不畅。原文脉洪滑甚实，或七八动一止，止在左部，为阳明实热兼肝气不舒；又左右脉弦硬间现结脉，症见胸中烦热、怔忡、便干，为阳盛阴亏、热迫心胃。热郁气阻，脉道不利，故结。"}, {"name": "主痰瘀互结", "desc": "结脉主气血痰瘀互结、络脉不通。原文阴疟经年，寒热喘逆痰升，左脉已结疟母，病在厥阴少阴，邪混气血为难治。疟母成形，痰瘀凝滞，络脉阻塞，脉气断续，故见结脉。"}, {"name": "主火郁上壅", "desc": "结脉主少阴之火不降、上焦气壅。原文左寸搏指（标为结），右关微实，因惊气乱，火不降而气壅，症见痞闷气逆、自汗、嗌干。火郁于上，气机壅滞，脉道不利，故结。"}], "n": {"主气滞": 1, "主热郁": 2, "主痰瘀互结": 1, "主火郁上壅": 1}, "a": {"10432": "主火郁上壅", "11309": "主痰瘀互结", "12532": "主气滞", "20026": "主热郁", "20378": "主热郁"}, "t": 5, "np": 0}, "pe:关+实": {"o": "关·实脉总起来主邪实壅盛于中焦，以脾胃为病位核心，兼涉肝胆。实脉主邪气实，关部候中焦，故凡有形实邪内结、气机壅滞者皆可见之。其具体所主，因兼脉不同而有所偏重：兼弦则肝木太过、气逆壅盛；兼滑则痰热实邪壅盛；兼大则邪热壅盛、脾胃邪实；兼数则食积化热、内结胃肠；兼沉则里实积滞、宿垢痰浊寒凝内阻。此外，关部虚实并见者，又主虚实夹杂、痰火内壅兼气火不足。各类之间，以“邪实壅滞”为共同病机基础，热盛、痰浊、食积、寒凝、气逆等为不同兼邪之偏性，而虚实夹杂一类则示实邪与正虚并存之复杂局面。要之，关·实脉以实证为主，然亦须察兼脉以辨邪之性质与正之盛衰。", "c": [{"name": "主肝实气逆", "desc": "关·实脉见弦实或沉急，为肝木太过之候。原文谓“脉实而弦，此为太过，病在外，令人忘忽眩运”，又沉急主胁支满、小便难、头痛眼眩，皆肝气壅盛、疏泄失常、气逆上冲所致。"}, {"name": "主邪热壅盛", "desc": "关·大实脉主邪热壅盛、脾胃邪实。实为邪气实，大主病势盛，原文见关脉实大，一为土太过之脾胃邪实壅滞，一为胃火刑金之邪热壅盛，皆属邪实热盛范畴，热盛为性，壅滞为体。"}, {"name": "主虚实夹杂", "desc": "关·虚实脉为复合脉象统称，关滑数主痰火实，寸尺软小濡小主气火虚，合而总主虚实夹杂、痰火内壅兼气火不足。气火虚则痰不易出，痰火实则气逆壅盛，二者互为因果，故见关滑数而寸尺软弱。"}], "n": {"主肝实气逆": 2, "主邪热壅盛": 1, "主虚实夹杂": 1}, "a": {"19357": "主肝实气逆", "20080": "主邪热壅盛", "20706": "主虚实夹杂", "23990": "主肝实气逆"}, "t": 4, "np": 0}, "s:转豆": {"o": "转豆脉总属真脏死脉，主胃气竭绝、脏气败绝，尤以心绝为直接对应。其脉来短促坚硬、旋转如豆、躁疾无从容之态，失去胃气柔和之象，故原文断为'死'。各类病机相互关联：胃气竭绝是根本，脏气败绝是整体后果，心绝则是具体脏腑定位。三者层层递进，共同说明转豆脉为危重病候、预后凶险之象，非寻常病脉可比。", "c": [{"name": "主胃气竭绝", "desc": "转豆脉短促坚硬、旋转如豆，无上下从容之态，是胃气竭绝、真脏脉见之象。原文断为'死'，强调脉无胃神根，脏气已败，与危重病候相应，非寻常病脉可比。"}, {"name": "主心绝", "desc": "原文列真脏绝脉，心绝之脉为'转豆躁疾'，如豆旋转急促躁动，厥厥动摇。此乃心之真气将绝、胃气已无、真脏独见之象，故主死，预后凶险。"}, {"name": "主脏气败绝", "desc": "转豆脉与屋漏、雀啄、弹石、解索等怪脉并列，皆无胃气柔和之象。'脉病人不病'而见此类脉者死，说明脏气败绝、脉失冲和，非独心绝，亦反映整体脏气衰败。"}], "n": {"主胃气竭绝": 1, "主心绝": 2, "主脏气败绝": 1}, "a": {"21188": "主胃气竭绝", "21823": "主脏气败绝", "26549": "主心绝", "26658": "主心绝"}, "t": 4, "np": 0}, "pe:关+细": {"o": "关·细脉总以正虚为纲，主气血不足、阴液亏虚及脏腑虚弱。细脉为脉道不充之象，非实邪所致。其病机可因兼脉与部位不同而分：细而无力多主气虚，细而涩多主阴血亏虚兼气滞，细而沉多主里虚阳弱或虚寒，细而数多主阴虚内热。关脉候脾胃，右关细主脾肺气虚，左关细主肝血不足，尺部细主肾阴亏虚。各类之间以虚为核心，或气虚，或阴亏，或阳虚，或虚中夹滞，总属不足之候。", "c": [{"name": "主气虚", "desc": "细脉主气血不足，脉道不充。右关细耎无力为脾肺气虚，右寸弱、右关弱、右尺细、左寸细等皆示肺、中焦、膀胱、小肠之气虚，气化无力。气虚推动无力，故脉细而弱，症见小便不利、咳呛痰血等。"}], "n": {"主气虚": 2}, "a": {"15942": "主气虚", "25096": "主气虚"}, "t": 2, "np": 0}, "pe:寸+濡": {"o": "寸·濡脉总起来主虚与湿，并可涉及危重之候。其核心病机为气虚，尤以肺脾气虚为主，因濡脉无力，主气衰鼓动不足；脾虚运化失职则湿邪内停，故濡又主湿。若虚阳不潜，浮越于上，则见虚阳上浮之象，脉可兼数或浮大。若脉失胃气柔和，出现屋漏、雀啄等怪脉，则主胃气败绝、脏气衰微之危候。各类之间以虚为根本，湿由虚生，虚阳上浮为虚之变，危候为虚之极，层层递进，总不离乎正气亏虚。", "c": [{"name": "主气虚", "desc": "寸·濡脉主肺脾气虚。原文右寸微主肺气有损，右关濡主中气不足，寸关皆涩主脾肺俱虚。濡为气虚无力鼓动之象，故见气短、咳嗽、乏力等症。"}], "n": {"主气虚": 1}, "a": {"24710": "主气虚"}, "t": 1, "np": 0}, "ps:右尺+细": {"o": "右尺细脉总属虚证，主下焦元气亏虚。其类有三：一为命火衰微，火不生土而晨泄；二为下焦气弱，气化不行而便闭；三为膀胱气虚，水道不利而小便难。三者皆以右尺细为共同脉象，反映肾与膀胱阳气不足、气弱不充。细脉主虚，右尺候肾，故其病机核心为下焦阳气虚衰，或火衰，或气弱，或膀胱气化无力，总不离虚损一端。", "c": [{"name": "主命火衰微", "desc": "右尺细弱为命门火衰之征。原文言右尺细弱，断为命火衰微，火衰则不能温煦脾土，致晨泄暴注。细弱之脉反映阳气不足，鼓动无力，故主肾阳亏虚、命火式微之病机。"}, {"name": "主下焦气弱", "desc": "右尺细如丝主下焦气弱。原文见六脉微弱，右尺细如丝，断为下焦气弱，膀胱气化无力，致大便不通。细为气弱不充脉道，故主下焦元气虚衰、气化不行之病机。"}, {"name": "主膀胱气虚", "desc": "右尺脉细主膀胱气弱。原文明言右尺脉细为膀胱气弱，气弱则推动无力，小便不利。细脉反映气弱不充，故主膀胱气虚、气化失司之病机。"}], "n": {"主命火衰微": 1, "主下焦气弱": 1, "主膀胱气虚": 1}, "a": {"7789": "主命火衰微", "17233": "主下焦气弱", "25096": "主膀胱气虚"}, "t": 3, "np": 0}, "u:脉闭": {"o": "脉闭脉总属邪闭脉道、气血不通之候，非虚证。其主病机有三：一为阳衰，元阳衰微、命门火绝，阳气不能鼓动血脉；二为毒闭，传染毒菌充塞心脏，心阳痹阻、心脏麻痹；三为痰闭，顽痰壅塞经络，气血不通。三者虽病因不同，然皆致脉道闭阻，故见六脉皆闭、重按不见。阳衰者属正虚至极，毒闭、痰闭属邪实壅塞，临证当结合兼症辨其虚实，分别施以回阳、解毒、豁痰通闭之法。", "c": [{"name": "主阳衰", "desc": "脉闭因元阳衰微、命门相火将绝，阳气不能鼓动血脉所致。原文言霍乱六脉皆闭，两目已瞑，气息已无，治以白通加猪胆汁汤，用人尿、猪胆汁引阳入阴，救垂绝之阳，故脉闭主阳衰危候。"}, {"name": "主毒闭", "desc": "脉闭因传染毒菌充塞心脏，致心脏麻痹、血脉不通。原文言霍乱六脉皆闭，乃毒菌壅塞、心阳痹阻之象，治宜兴奋心脏与扫除毒菌并用，如急救回生丹、卫生防疫宝丹，故脉闭主毒邪闭阻心脉。"}, {"name": "主痰闭", "desc": "脉闭因顽痰壅塞经络，气血不通。原文言壮年癫狂失心，六脉皆闭，重按亦分毫不见，明言“顽痰能闭脉”，治以大承气汤加赭石、甘遂峻下痰热，服后下痰而脉通，故脉闭主顽痰闭阻。"}], "n": {"主阳衰": 1, "主毒闭": 1, "主痰闭": 1}, "a": {"20107": "主阳衰", "20187": "主毒闭", "20316": "主痰闭"}, "t": 3, "np": 0}, "rc:沉取+大+洪": {"o": "沉取大洪脉总起来主虚实两端，以虚证为多。其核心病机是阳气浮越于外而内里虚寒或气血亏虚，故脉虽洪大，重按却无力、微细、如无甚至散乱，形成‘洪大为假、重按为真’的辨证关键。具体可分为虚阳外浮、气血两虚、虚阳夹痰、阳脱危候、气虚阳浮等类，皆属本虚标实或纯虚之候；仅阳明腑实一类为实热内结，脉必重按有力。各类之间以‘重按有力无力’为分水岭：无力者多虚，有力者多实。虚类中，虚阳外浮与气虚阳浮相近，但前者偏阳气浮越、格阳戴阳，后者偏中气不足、逼阳外浮；虚阳夹痰兼痰热内阻，阳脱危候则元气涣散、病情最重。实类仅阳明腑实，因热结于里，脉沉取有力。总之，此脉以虚阳浮越为主线，临证须凭沉取之力辨真假寒热。", "c": [{"name": "主虚阳外浮", "desc": "脉洪大而重按无力或全无，为阳气虚衰、虚阳浮越于外之假热。原文如脉洪大而空、重按如无、重按全无，皆断为格阳戴阳或命门火衰，身热面赤却肢冷、舌胖润，故非实热。"}, {"name": "主气血两虚", "desc": "洪大而重按如无，主气血亏虚、阳气无根。如产妇误汗后脉洪大重按如无，断为气血两虚；亦以重按如无知为气血两虚，强调有力无力辨虚实，洪大为虚阳外浮之象。"}, {"name": "主虚阳夹痰", "desc": "脉洪大而沉取滑，主虚阳不潜、痰热内阻。如右寸关脉顿洪大沉取甚滑，断为虚阳上浮、胃中痰热；脉洪大重按微细，为虚阳浮越兼痰热内扰、真阴亏损，属本虚标实。"}, {"name": "主阳脱危候", "desc": "脉洪大无伦、重取散乱，主真阳欲脱、元气涣散。如伤寒误治后脉洪大无伦重取则散，伴神昏蜷卧，断为少阴寒化、阳脱危候，与‘脉反散大，乃真阳欲脱之机’相应。"}, {"name": "主气虚阳浮", "desc": "脉大而无力，主中气虚寒、逼阳外浮。如老人痢疾六脉更大而无力，断为老人脉大为虚，非热；泻痢年余脉洪大重按全无，为命门火衰、脾土虚寒而假热，皆宜温补。"}, {"name": "主阳明腑实", "desc": "脉重按有力，主热邪内结阳明之腑。如温疟患儿脉非洪大而重按有力，说明热已内结阳明，非在表之洪大；因久病羸弱，热虽实而脉不浮洪，主阳明腑实兼少阳不和。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主虚阳外浮": 2, "主气血两虚": 2, "主虚阳夹痰": 2, "主阳脱危候": 1, "主气虚阳浮": 1, "主阳明腑实": 1, "其他": 0}, "a": {"3345": "主虚阳外浮", "3806": "主虚阳夹痰", "4097": "主气血两虚", "4098": "主气血两虚", "4104": "主虚阳外浮", "7970": "主虚阳夹痰", "16072": "主阳脱危候", "16146": "主气虚阳浮", "20331": "主阳明腑实"}, "t": 9, "np": 0}, "pc2:两寸+滑+大": {"o": "两寸滑大脉总以中上二焦痰、火、气、食壅盛为基本病机，其脉象滑主痰、大主实，见于寸关，故病位多在中上焦。然原文每与两尺沉微或沉弱并见，形成上盛下虚之格局，故其病机常非单纯实证，而是痰火气滞壅于上，兼下元不足或血虚于下。上述五类中，痰盛、火旺、气滞为邪实之象，血虚、下元不足为正虚之因，虚实相兼，上实下虚，故治疗既需清化痰火、行气消积，又当顾护下元、养血和血。诸类之间相互关联，痰火每因气滞而升，气滞又因血虚而甚，下虚则上实更易形成，临证当合参脉症，全面辨析。", "c": [{"name": "主痰盛", "desc": "滑脉主痰，大脉主实，两寸滑大有力，为痰浊壅盛于中上二焦之象。原文多断为“中焦有痰”“痰积胸膈”，症见呕吐眩晕、心痛彻背、探吐其食乃已，皆痰浊阻滞气机所致。"}, {"name": "主火旺", "desc": "滑大有力亦主火邪亢盛。原文谓“肝胆火旺”“火性急速”，因怒气触发，火乘于络，上冲头目，故见眼赤肿痛、白泡突生、太阳疼痛、大便不行，皆火邪上炎之候。"}, {"name": "主气滞", "desc": "大脉主邪气盛，滑脉主痰食壅滞，寸关滑大提示中上焦气机壅滞。原文断为“气滞痰食壅于中上”“血虚气滞”，症见胃脘疼痛拒按、饥不能食，气滞不通则痛，故用行气消积之品而安。"}, {"name": "主血虚", "desc": "两寸关滑大而两尺沉弱，为上盛下虚之象。原文断为“血虚气滞”，年高之人下元血虚不足，脉见尺部沉弱，血虚失养则胃脘作痛，故以养血和血之品收功。"}, {"name": "主下元不足", "desc": "两寸滑大而两尺沉微或沉弱，提示下焦阳虚或气血不足。原文屡言“下元不足”“下焦阳虚”，因下虚不能制上，痰火乘虚上逆，故见上实下虚之候，治当兼顾下元。"}, {"name": "其他", "desc": "无法归入上述类别的段落"}], "n": {"主痰盛": 6, "主火旺": 0, "主气滞": 0, "主血虚": 2, "主下元不足": 0, "其他": 0}, "a": {"3899": "主痰盛", "4302": "主痰盛", "6138": "主痰盛", "6170": "主血虚", "6218": "主痰盛", "6433": "主痰盛", "6465": "主血虚", "6513": "主痰盛"}, "t": 8, "np": 0}});